
/*!
 * Casa Besports — aide en ligne des espaces d’administration (rédaction, Gazette, Atelier, CRM Drakkar, comptes).
 * Une fiche = { id, titre, espaces, ecrans, resume, motscles, sections: [{ h, p: [], l: [], code }] }.
 * Fichier partagé par le site, l’application et l’Atelier.
 */
var CASA_AIDE = [
  { id: 'prise-en-main', titre: 'Prise en main de l’espace rédaction', espaces: ['redaction'], ecrans: ['redaction'], motscles: 'tableau de bord menu onglets rôles',
    resume: 'Les écrans de l’espace rédaction, et qui peut faire quoi.',
    sections: [
      { h: 'Les écrans', l: ['Tableau de bord : ce qui attend votre action et l’activité récente.', 'Articles : la liste complète, avec recherche plein texte et filtres.', 'Relecture : la file des articles soumis.', 'La une : l’ordre des articles de l’accueil du site et de l’application.', 'Éditions · Gazette : titres, éditions, chemin de fer, pages et suivi de production.', 'Médiathèque : photos et vidéos, crédits, droits par canal, contenus d’agence.', 'Le Fil : contenus échangés avec les rédactions partenaires.', 'IA : prompts, fournisseurs et suivi de l’utilisation.', 'Équipe et règles : droits de chacun et règles de publication.', 'Exports (administrateur) : données éditoriales par canal et par période.'] },
      { h: 'Les rôles', l: ['Administrateur principal : valide, publie, gère la une, les règles, les prompts et les titres.', 'Chef d’édition (compte « collaborateur ») : rédige, gère la une et la Gazette ; peut publier sans relecture si la règle le permet.', 'Rédacteur : rédige et soumet ; ne publie jamais seul.'] },
      { h: 'L’aide', p: ['Le bouton « ? » en haut à droite ouvre les fiches. Les fiches liées à l’écran affiché apparaissent en premier.'] }
    ] },
  { id: 'workflow', titre: 'Gestion du workflow : rédiger, soumettre, relire, publier', espaces: ['redaction', 'admin'], ecrans: ['workflow', 'articles', 'redaction'], motscles: 'relecture soumettre publier programmer corrections refuser statut',
    resume: 'Le circuit d’un article, du brouillon à la mise en ligne.',
    sections: [
      { h: 'Les statuts', l: ['Brouillon : l’auteur écrit.', 'En relecture : l’article est verrouillé pour l’auteur.', 'Corrections demandées : l’auteur reçoit la note de l’administrateur.', 'Programmé : publication à la date choisie.', 'Publié : visible sur le site et dans l’application.', 'Refusé : archivé avec son motif.'] },
      { h: 'Version en ligne', p: ['Un article publié garde sa version en ligne pendant qu’on le modifie : « Remettre en rédaction » rouvre l’édition sans le retirer du site. « Retirer du site » le dépublie.'] },
      { h: 'Contrôle qualité', p: ['La checklist (titre, chapeau, longueur, image et texte alternatif, intertitre, clubs liés) donne un score sur 100. Les règles de publication décident si un score faible bloque ou alerte seulement.'] }
    ] },
  { id: 'regles', titre: 'Contraintes de publication bloquantes ou non bloquantes', espaces: ['redaction', 'admin'], ecrans: ['roles', 'workflow'], motscles: 'règles contraintes alerte passer outre relecture droits bloquant',
    resume: 'Rendre certaines contraintes non bloquantes pour un rôle donné.',
    sections: [
      { h: 'Le principe', p: ['Chaque contrainte a un mode par rôle : bloquante, non bloquante (alerte) ou désactivée. L’administrateur les règle dans « Équipe et règles ».'] },
      { h: 'Les contraintes', l: ['Publication web sans passer par la relecture.', 'Score qualité d’au moins 50/100.', 'Texte alternatif de l’image.', 'Photo autorisée sur le site (droits par canal) : toujours bloquante, même pour l’administrateur.', 'Au moins un club lié.', 'Titre de 80 caractères maximum.'] },
      { h: 'Passer outre', p: ['Avec une contrainte non bloquante, un message d’alerte s’affiche : le membre choisit « Passer outre et continuer » ou « Corriger l’article ». S’il passe outre, l’historique de l’article note les contraintes levées.', 'Exemple : avec « relecture » en non bloquante pour les chefs d’édition, le bouton « Publier sans relecture » apparaît pour eux. Le serveur vérifie la règle à chaque publication.'] }
    ] },
  { id: 'versions', titre: 'Versions d’article : consulter, comparer, restaurer', espaces: ['redaction'], ecrans: ['articles'], motscles: 'version historique comparer différence restaurer nommer',
    resume: 'Chaque action enregistre une version que l’on peut relire, comparer ou rétablir.',
    sections: [
      { h: 'Quand une version est créée', p: ['À chaque action nommée : brouillon enregistré, soumission, corrections, publication, restauration, reprise du Fil. Une version identique à la précédente n’est pas dupliquée. Les 40 dernières versions sont gardées.', 'Vous pouvez aussi nommer une version (« version imprimée », « avant relecture ») dans le panneau « Versions ».'] },
      { h: 'Consulter et comparer', l: ['Consulter : affiche la version comme un aperçu, sans toucher à l’article.', 'Comparer : texte ajouté souligné en vert, texte supprimé barré en rouge, pour le titre, le chapeau et le corps, plus la liste des autres champs modifiés (image, rubrique, type…).'] },
      { h: 'Restaurer', p: ['« Restaurer » remet le contenu de la version dans l’article et crée une nouvelle version : rien n’est perdu, on peut revenir en arrière.'] }
    ] },
  { id: 'collage', titre: 'Copier-coller et types d’article', espaces: ['redaction'], ecrans: ['articles'], motscles: 'coller copier mise en forme gras italique intertitre brève type',
    resume: 'Les mises en forme compatibles sont conservées au collage.',
    sections: [
      { h: 'Au collage', p: ['Collez depuis un autre article, un traitement de texte ou une page web : intertitres, citations, listes, gras et italique sont convertis au format de l’éditeur.'] },
      { h: 'Selon le type de l’article', l: ['Article et portrait : toutes les mises en forme.', 'Tribune : intertitres, citations, gras, italique.', 'Compte rendu de match : intertitres, listes, gras.', 'Brève : gras et italique seulement.'] },
      { h: 'Mise en forme non compatible', p: ['Le paragraphe passe en texte simple, et un message indique combien de mises en forme ont été converties.'] }
    ] },
  { id: 'recherche', titre: 'Recherche et articles similaires', espaces: ['redaction'], ecrans: ['articles'], motscles: 'recherche filtre plein texte similaires pertinence lier à lire aussi',
    resume: 'Trouver un article par n’importe quel mot, et relier les articles proches.',
    sections: [
      { h: 'Recherche plein texte', p: ['Dans « Articles », chaque mot tapé doit apparaître dans le titre, le chapeau, le texte, la rubrique, l’auteur, le titre imprimé ou le nom d’un club cité. Un extrait montre le passage trouvé.'], l: ['Filtres : statut, type, discipline, auteur, période, en ligne seulement.', 'Tri : plus récents, pertinence ou titre.'] },
      { h: 'Articles similaires', p: ['Dans l’éditeur, les 10 articles les plus proches s’affichent en priorité (mots communs, même discipline, mêmes clubs). La recherche classique reste juste en dessous.', '« Lier » ajoute l’article à la rubrique « À lire aussi » affichée sous l’article publié.'] }
    ] },
  { id: 'une', titre: 'Gestion de la une', espaces: ['redaction'], ecrans: ['une'], motscles: 'une accueil position épingler ajouter remplacer ouverture',
    resume: 'Choisir l’ordre des articles de l’accueil, avec des positions épinglées.',
    sections: [
      { h: 'Les positions', p: ['Six positions : la première est l’ouverture de l’accueil, les suivantes alimentent « À la une » et les dernières actus.'] },
      { h: 'Insérer un article', l: ['Positionner et ajouter : l’article prend la position choisie et décale les suivants. Les articles épinglés ne bougent pas.', 'Positionner et remplacer : l’article prend la place de celui qui occupe la position.', 'Si la position est occupée par un article épinglé, un message d’erreur s’affiche.'] },
      { h: 'Articles insérables', p: ['Tout article en ligne : publié, ou publié puis rouvert pour une modification (sa version en ligne reste affichée). Un article jamais publié ne peut pas aller à la une.'] }
    ] },
  { id: 'editions', titre: 'L’administration des éditions', espaces: ['redaction', 'admin'], ecrans: ['editions'], motscles: 'gazette titre édition numéro chemin de fer page statut boucler',
    resume: 'Titres, éditions, chemin de fer et pages de la Gazette.',
    sections: [
      { h: 'Titres et éditions', p: ['Un titre (La Gazette du Cotentin, un programme de match, un hors-série…) a sa charte, sa grille, ses rubriques et ses modèles. Chaque titre a ses éditions (N°0, N°1…).'] },
      { h: 'Le chemin de fer', p: ['Toutes les pages de l’édition en vignettes : articles, photos, publicités, éléments fixes, emplacements réservés hachurés en rouge, cadenas sur les pages héritées verrouillées.'] },
      { h: 'Les pages', l: ['Statut : à faire, en cours, prête, validée.', 'Ajouter un article, une photo, une publicité ou un élément fixe : placé dans le premier emplacement libre du carton choisi.', 'Sélectionner un bloc pour le déplacer, le redimensionner, changer de carton, de corps ou de titre.'] },
      { h: 'Boucler une édition', p: ['« Boucler l’édition » la passe en lecture seule : ses pages peuvent alors être héritées par l’édition suivante. L’administrateur peut la rouvrir pour une correction, qui se répercute sur les pages héritées verrouillées.'] }
    ] },
  { id: 'gazette-rubriques', titre: 'La Gazette : cahiers, rubriques et détail choc 🔥', espaces: ['redaction', 'admin'], ecrans: ['editions'], motscles: 'gazette détail choc rubrique cahier question qui divise rétro lexique humeur baromètre charte bandeau source',
    resume: 'Les cinq cahiers du journal, les rubriques récurrentes et la règle du détail choc.',
    sections: [
      { h: 'Cinq cahiers', p: ['À la une, Le terrain, Les gens, Le territoire, La pause. Le sommaire de la liseuse les regroupe automatiquement, page par page.'] },
      { h: 'Les rubriques récurrentes', l: ['Le détail choc 🔥 : un fait vérifié qui change le regard sur une histoire, en pleine page noire ou en encadré sur une page.', 'La question qui divise : deux camps, des arguments, et le lecteur donne son avis (il l’envoie à la rédaction depuis la liseuse).', 'Rétro : il y a dix, vingt ou trente ans, un événement sportif du territoire.', 'Le lexique : les mots du bord de terrain, sport par sport.', 'L’humeur : le baromètre du mois et le classement qui ne sert à rien.'] },
      { h: 'La règle du détail choc', l: ['Un fait, jamais une rumeur : il doit être vérifiable et sourcé.', 'La source est imprimée sous l’encadré (archives, fédération, presse, document officiel).', 'Dans le chemin de fer, placez le modèle « Le détail choc 🔥 (encadré) » sur une page, ou « pleine page noire » pour la page dédiée, puis choisissez l’article qui le contient.', 'Avant de valider la page, l’administrateur vérifie la source.'] },
      { h: 'La charte', p: ['La Gazette suit la direction artistique du site : noir et blanc, titres en capitales League Spartan posés sur des bandeaux comme le logo, texte courant en Source Serif. Seule la page du détail choc passe en négatif, blanc sur noir.'] }
    ] },
  { id: 'heritage', titre: 'Hériter des pages depuis une édition bouclée', espaces: ['redaction'], ecrans: ['editions'], motscles: 'héritage hériter dissocier verrouillée page héritée nouvelle édition',
    resume: 'Associer automatiquement les pages d’une édition bouclée à la suivante.',
    sections: [
      { h: 'Créer l’édition suivante', p: ['« Nouvelle édition » propose d’hériter des pages de la dernière édition bouclée. Toutes les pages sont associées par défaut ; décochez celles qui doivent repartir vierges.'] },
      { h: 'Pages verrouillées', p: ['Une page héritée identique reste verrouillée : elle affiche le contenu de sa page source et suit ses corrections (héritage actif). Les éléments fixes y attendent la livraison propre à la nouvelle édition.'] },
      { h: 'Dissocier', p: ['« Dissocier pour modifier » rend la page modifiable. Elle devient une page héritée dont les éléments restent marqués « hérité » tant qu’ils ne sont pas modifiés : vous pouvez en changer une partie ou la totalité. « Relier à la page source » annule la dissociation.'] }
    ] },
  { id: 'reprise', titre: 'Reprendre une page d’un autre titre', espaces: ['redaction'], ecrans: ['editions'], motscles: 'reprendre réutiliser page titre charte modèles appliquer',
    resume: 'Réutiliser une page d’un autre titre, quelle que soit sa date de parution.',
    sections: [
      { h: 'Reprendre', p: ['« Reprendre une page… » : choisissez le titre source, l’édition (toutes dates) et la page. Elle s’ajoute à la fin de l’édition ouverte.'] },
      { h: 'Charte différente', p: ['Si la charte du titre source diffère, la page arrive telle quelle avec le bouton « Appliquer nos modèles » : la grille est recalculée, chaque bloc prend le carton équivalent du titre et la rubrique la plus proche. Les couleurs et la police suivent la charte du titre.'] }
    ] },
  { id: 'cartons', titre: 'Cartons, modèles et titre par défaut', espaces: ['redaction', 'admin'], ecrans: ['editions'], motscles: 'carton modèle titre par défaut version imprimée brève le chiffre',
    resume: 'Un titre par défaut s’applique automatiquement à la version imprimée.',
    sections: [
      { h: 'Le titre par défaut', p: ['Dans « Titres et modèles », chaque carton peut avoir un titre par défaut (« En bref », « Le chiffre », « Tribune »…). Un article placé dans ce carton prend ce titre dans la version imprimée, sauf si le titre a été modifié à la main dans la page.', 'Dans l’éditeur, le champ « Titre de la version imprimée » indique le titre par défaut qui s’applique.'] },
      { h: 'Modèles et rubriques', p: ['L’administrateur ajoute des modèles (contenu, colonnes, lignes, titre par défaut), édite les rubriques et crée de nouveaux titres (tabloïd, A4 ou A5).'] }
    ] },
  { id: 'organisation', titre: 'Organisation et ajustement automatiques', espaces: ['redaction'], ecrans: ['editions'], motscles: 'organiser automatiquement ajuster texte signes corps calibrage hors page',
    resume: 'Ranger les blocs dans la page et caler les textes.',
    sections: [
      { h: 'Organiser automatiquement', p: ['Les publicités et les blocs dont la position est épinglée restent en place. Les autres sont rangés par importance : l’article le plus long en ouverture, puis les autres articles, les photos et les éléments fixes. Un bloc sans place est signalé « hors page ».'] },
      { h: 'Ajuster les textes', p: ['Chaque article affiche son calage : « Ajusté », « Trop long de 240 signes » ou « Manque 120 signes ». L’ajustement choisit le corps (8,5 à 10,5 pt), puis agrandit le bloc vers le bas si la place le permet. Les textes encore trop longs sont listés avec le nombre de signes à couper.'] }
    ] },
  { id: 'fixes', titre: 'Éléments fixes : réserver un emplacement', espaces: ['redaction', 'admin'], ecrans: ['editions'], motscles: 'élément fixe réserver réserve météo jeux classement agenda marées livrer api raccourci',
    resume: 'Réserver la place d’un élément fixe avant d’avoir son visuel.',
    sections: [
      { h: 'Réserver', p: ['Comme un ordre de publicité, placez un élément fixe (météo, jeux, classement, agenda, résultats, marées…) avant d’avoir le visuel : l’emplacement est hachuré « Réservé ». Les réserves en attente s’affichent dans le suivi de production.'] },
      { h: 'Livrer', l: ['« Générer depuis les données » pour la météo, le classement, l’agenda, les résultats et le sommaire.', '« Livrer… » pour un texte ou un visuel.', 'À la réception, toutes les réserves de cet élément dans l’édition se remplissent.', 'L’ours et le bulletin d’abonnement sont permanents : livrés une fois pour toutes les éditions.'] },
      { h: 'Raccourci', p: ['Dans le suivi de production, recherchez un élément par nom ou par tag, choisissez la page : il se place dans le premier emplacement libre.'] },
      { h: 'Livraison par l’API', p: ['Un fournisseur (prestataire de jeux, service météo…) peut livrer directement. Renseignez PROD_API_TOKEN dans le fichier .env du serveur, puis :'], code: 'POST /api/redac/prod/fixes/meteo/livrer\nAuthorization: Bearer <PROD_API_TOKEN>\nContent-Type: application/json\n\n{ "edition": "<identifiant facultatif>", "text": "Samedi : 14° / 8°…", "img": "https://…/meteo.png" }' }
    ] },
  { id: 'suivi', titre: 'Suivi de production et plan plein écran', espaces: ['redaction'], ecrans: ['editions'], motscles: 'suivi production plein écran plan vue globale pages statut réserves',
    resume: 'Voir l’avancement de toutes les éditions d’un titre.',
    sections: [
      { h: 'Suivi de production', p: ['Compteurs de pages par statut, réserves en attente avec leurs actions, catalogue des éléments fixes avec leur état de livraison et le nombre de pages où ils sont placés.'] },
      { h: 'Plan plein écran', p: ['« Afficher le plan en plein écran » montre toutes les éditions du titre les unes sous les autres, page par page. Une vignette ouvre la page correspondante.'] }
    ] },
  { id: 'fil', titre: 'Le Fil : échanger des contenus entre rédactions', espaces: ['redaction', 'admin', 'atelier'], ecrans: ['fil', 'atelier-fil'], motscles: 'fil échange partenaire rédaction instance envoyer recevoir reprendre activation clé',
    resume: 'Envoyer et recevoir des contenus bruts avec d’autres rédactions, y compris sur d’autres plateformes.',
    sections: [
      { h: 'Envoyer', p: ['Depuis un article : « Envoyer sur le Fil », choisissez les partenaires. Partent le titre, le chapeau, le texte, les crédits et, si ses droits le permettent pour les partenaires, la photo. Depuis l’Atelier : un visuel et sa légende.'] },
      { h: 'Recevoir', p: ['Les contenus reçus arrivent dans « Le Fil » avec leur source. « Reprendre en brouillon » crée un article qui suit la relecture normale ; la source est citée en fin de texte. Rien n’est publié automatiquement.'] },
      { h: 'Activation (administrateur)', p: ['Dans le fichier .env du serveur :'], code: 'FIL_NOM=Casa Besports\nFIL_PARTENAIRES=Rédaction A|https://rédaction-a.fr|clé-partagée-A;Rédaction B|https://rédaction-b.fr|clé-partagée-B' },
      { h: 'Sécurité', p: ['Chaque envoi est signé avec la clé partagée (HMAC-SHA256) : un contenu dont la signature ne correspond à aucun partenaire est refusé. Communiquez la clé à votre partenaire par un canal sûr.'] }
    ] },
  { id: 'afp', titre: 'Utiliser les contenus d’agence (AFP)', espaces: ['redaction', 'admin', 'atelier'], ecrans: ['medias', 'atelier-agence'], motscles: 'afp agence photo vidéo abonné importer crédit droits apicore',
    resume: 'Rechercher, importer et utiliser les photos et vidéos AFP, pour les clients disposant d’un compte AFP.',
    sections: [
      { h: 'Rechercher et importer', p: ['Médiathèque › Agence (AFP) : choisissez photos ou vidéos, tapez vos mots, puis « Importer ». Le média arrive dans la médiathèque avec sa légende, le crédit « AFP » et les droits de votre contrat. Dans l’Atelier, le même import alimente « Mes photos » et le Studio Vidéo.'] },
      { h: 'Configuration (administrateur)', p: ['Réservé aux clients ayant un compte AFP. Renseignez les identifiants fournis par l’AFP dans le fichier .env :'], code: 'AFP_CLIENT_ID=…\nAFP_CLIENT_SECRET=…\nAFP_USERNAME=…\nAFP_PASSWORD=…\n# canaux couverts par votre contrat\nAFP_CANAUX=site,appli,gazette' },
      { h: 'Droits', p: ['Les canaux absents d’AFP_CANAUX sont « non autorisés » : par exemple, une photo AFP ne part pas sur le Fil vers les partenaires. Le crédit AFP accompagne le média partout.'] }
    ] },
  { id: 'medias', titre: 'Médiathèque : indexation, droits par canal, durée des vidéos', espaces: ['redaction', 'atelier'], ecrans: ['medias', 'atelier'], motscles: 'médiathèque photo vidéo légende crédit droits libre de droit canal durée recherche',
    resume: 'Retrouver une photo par sa légende ou son crédit, et régler ses droits canal par canal.',
    sections: [
      { h: 'Indexation', p: ['La recherche porte sur la légende, le crédit, les mots-clés et les titres des articles qui utilisent la photo.'] },
      { h: 'Libre de droit, canal par canal', l: ['Canaux : site, application, Gazette papier, réseaux sociaux, partenaires (Fil).', 'Pour chaque canal : libre de droit, autorisé avec crédit, non autorisé, ou à vérifier.', 'Une photo importée est « à vérifier » partout tant qu’on ne l’a pas renseignée.', 'Les droits sont contrôlés à la publication (site), au placement en page (Gazette), à l’envoi sur le Fil (partenaires) et dans l’Atelier (réseaux sociaux).'] },
      { h: 'Durée des vidéos', p: ['La durée (minutes:secondes) se renseigne dans la fiche de la vidéo ou dans l’éditeur d’article. Elle est transmise au site à la publication et s’affiche sur les vignettes.'] }
    ] },
  { id: 'ia', titre: 'Personnalisation de l’IA : prompts, rôles et fournisseurs', espaces: ['redaction', 'admin', 'atelier'], ecrans: ['ia', 'articles', 'atelier'], motscles: 'ia prompt rôle fournisseur claude chatgpt mistral consigne assistant',
    resume: 'Des prompts réservés à certains rôles, et le choix du fournisseur d’IA champ par champ.',
    sections: [
      { h: 'Les prompts', p: ['Un prompt est une consigne réutilisable (proposer des titres, rédiger le chapeau, relire, résumer, titre court pour la Gazette, référencement, message pour les réseaux, texte alternatif). L’administrateur peut les modifier, en créer et les réserver à des rôles.'], l: ['Variables : {{titre}}, {{chapo}}, {{texte}}, {{alt}}.'] },
      { h: 'Les fournisseurs', p: ['Sans clé, l’assistant intégré répond sans envoyer de données. Si plusieurs fournisseurs sont configurés, chacun choisit celui qui rédige un champ donné ; le choix est retenu champ par champ.'], code: 'ANTHROPIC_API_KEY=…   # Claude\nOPENAI_API_KEY=…      # ChatGPT\nMISTRAL_API_KEY=…     # Mistral' },
      { h: 'Toujours relu', p: ['Une proposition de l’IA ne s’applique qu’avec le bouton « Appliquer », et l’article suit ensuite la relecture normale.'] }
    ] },
  { id: 'ia-suivi', titre: 'Suivi de l’utilisation de l’IA', espaces: ['redaction', 'admin'], ecrans: ['ia'], motscles: 'historique ia journal compteur export année prompts utilisés',
    resume: 'Qui a utilisé quel prompt, sur quels articles.',
    sections: [
      { h: 'Le journal', p: ['Chaque demande est notée : date, membre, rôle, prompt, fournisseur, article. Filtres par année, membre et prompt, avec le nombre de demandes et d’articles traités pour la sélection.'] },
      { h: 'Grands volumes', p: ['L’affichage se fait par tranches (« Afficher plus de lignes ») : au-delà de 10 000 lignes, rien n’est tronqué. « Exporter l’année en cours » produit un fichier CSV complet.'] }
    ] },
  { id: 'exports', titre: 'Exports personnalisés', espaces: ['admin'], ecrans: ['exports'], motscles: 'export csv json canal période données tableur',
    resume: 'Exporter les données éditoriales par canal et par période.',
    sections: [
      { h: 'Les données', l: ['Articles (statut, type, canaux, signes…).', 'Versions d’articles.', 'Pages des éditions (statut, héritage, réserves).', 'Médiathèque (crédits, droits par canal, durée).', 'Journal de l’IA.', 'Le Fil (reçus et envoyés).'] },
      { h: 'Les filtres', p: ['Canal (site, application, Gazette papier, réseaux sociaux, partenaires) et période (du… au…). Format CSV pour un tableur (séparateur point-virgule) ou JSON pour un autre logiciel. Un aperçu montre les premières lignes.'] }
    ] },
  { id: 'comptes', titre: 'Création et modification d’un utilisateur', espaces: ['admin', 'crm'], ecrans: ['roles', 'comptes'], motscles: 'compte utilisateur créer mot de passe provisoire désactiver réactiver équipe connexion',
    resume: 'Les comptes de l’équipe se gèrent sur la page « Comptes de l’équipe » (administrateur).',
    sections: [
      { h: 'Créer un compte', p: ['Dans Drakkar, « Comptes de l’équipe » (casabesports.fr/crm/comptes.html) : prénom et nom, e-mail et rôle, puis « Créer le compte ». Un mot de passe provisoire s’affiche une seule fois, avec l’adresse de connexion : transmettez-le de façon sûre.'] },
      { h: 'Modifier, désactiver', l: ['Le rôle se change directement dans la liste.', '« Nouveau mot de passe » en génère un autre, affiché une seule fois, et réactive le compte.', '« Désactiver » ferme immédiatement ses sessions ; ses articles et ses créations restent en place. « Réactiver » rouvre l’accès.', 'Vous ne pouvez pas retirer vos propres droits d’administrateur.'] },
      { h: 'Mon mot de passe', p: ['En bas de la page : mot de passe actuel puis nouveau mot de passe de 10 caractères minimum. Le changement ferme toutes vos sessions : reconnectez-vous avec le nouveau mot de passe.'] },
      { h: 'Correspondant de club', p: ['Choisissez le rôle « Correspondant de club » puis le club : le compte n’accède qu’à l’espace club de ce club (contenus guidés, fiche du club), jamais au reste de la rédaction ni au CRM.'] },
      { h: 'En ligne de commande', code: 'npm run admin -- --email membre@casabesports.fr --nom "Prénom Nom" --role redacteur\nnpm run admin -- --email club@exemple.fr --nom "Prénom Nom" --role club --club esph' }
    ] },
  { id: 'roles', titre: 'Gestion des rôles utilisateurs', espaces: ['admin', 'crm'], ecrans: ['roles', 'comptes'], motscles: 'rôle administrateur collaborateur rédacteur chef d’édition droits',
    resume: 'Ce que permet chaque rôle sur le site, la Gazette, l’Atelier et le CRM.',
    sections: [
      { h: 'Administrateur', l: ['Valide et publie, gère la une, les règles de publication, les prompts, les titres et modèles, les exports et les comptes.', 'Accède au CRM Drakkar et à l’Atelier.'] },
      { h: 'Collaborateur (chef d’édition)', l: ['Rédige et soumet, gère la une et la Gazette (éditions, pages, éléments fixes).', 'Publie sans relecture si la règle « relecture » est non bloquante pour son rôle.', 'Accède au CRM et à l’Atelier.'] },
      { h: 'Rédacteur', l: ['Rédige ses articles et les soumet ; ne publie jamais seul.', 'Ne modifie pas les articles des autres.', 'Accède à l’Atelier.'] },
      { h: 'Correspondant de club', l: ['Bénévole d’un club, rattaché à ce seul club.', 'Rédige avec des modèles guidés (compte rendu, annonce, bénévoles, résultats, portrait, agenda) et envoie à la rédaction ; ne publie jamais.', 'Propose la fiche pratique de son club, mise en ligne après validation.', 'Ne voit ni les articles des autres clubs, ni la une, ni la Gazette, ni le CRM.'] }
    ] },
  { id: 'sante', titre: 'Comprendre l’état de santé de la plateforme', espaces: ['admin'], ecrans: ['redaction', 'roles', 'exports'], motscles: 'santé état serveur base de données agents smtp instagram ia afp fil disque',
    resume: 'Un relevé en direct de chaque brique de la plateforme.',
    sections: [
      { h: 'Ce qui est vérifié', l: ['Base de données et espace occupé.', 'Agents autonomes (dernière exécution).', 'E-mails (SMTP), Instagram, IA (fournisseurs), AFP, Fil (partenaires et dernier échange).', 'Médias stockés et volume.'] },
      { h: 'Lire les voyants', p: ['Vert : en service. Or : facultatif et non configuré. Rouge : configuré mais en erreur, à vérifier dans les journaux du serveur.'] }
    ] },
  { id: 'crm', titre: 'Le CRM Drakkar : prise en main', espaces: ['admin', 'crm'], ecrans: ['crm', 'home', 'reports', 'settings'], motscles: 'crm drakkar aujourd’hui rapports paramètres rubriques accès pastilles société siret',
    resume: 'Les rubriques du CRM de l’équipe, qui peut y accéder et ce que signalent les pastilles.',
    sections: [
      { h: 'Accès', p: ['casabesports.fr/crm, pour les administrateurs et les collaborateurs (chefs d’édition). Les rédacteurs n’y ont pas accès. Les formulaires du site et de l’application y créent des contacts, traités par l’agent Qualification.'] },
      { h: 'Les rubriques', l: ['Pilotage : « Aujourd’hui » (validations en attente, point du jour, retards) et « Rapports ».', 'Relations : contacts, pipeline des affaires, campagnes et calendrier Instagram.', 'Organisation : agenda, tâches et équipe.', 'Finance : devis et factures, contrats partenaires.', 'Automatisation : agents autonomes, le Viking (IA) et le journal de bord.', 'Paramètres : coordonnées et mentions légales de la société (nom, adresse, SIRET, TVA, délai de paiement), réglages Instagram.'] },
      { h: 'Les pastilles', p: ['Un nombre à côté d’une rubrique signale ce qui attend : validations, tâches en retard, factures échues, contrats à renouveler sous 45 jours, publications Instagram à compléter, à valider ou en échec.'] },
      { h: 'L’aide', p: ['« Aide en ligne » dans la barre latérale (« ? » sur téléphone) ouvre ces fiches : celles de l’écran affiché viennent en premier, la recherche porte sur tout leur texte.'] }
    ] },
  { id: 'crm-contacts', titre: 'CRM : contacts, pipeline et qualification', espaces: ['admin', 'crm'], ecrans: ['contacts', 'pipe'], motscles: 'contact client prospect partenaire club annonceur abonné presse collectivité doublon rgpd consentement pipeline affaire étape probabilité relance',
    resume: 'Les fiches contacts, les affaires par étape et la qualification automatique.',
    sections: [
      { h: 'Contacts', p: ['Chaque contact a un type (partenaire, club, annonceur, abonné, supporter, prospect, presse, collectivité), une source et un consentement. L’agent Qualité des données fusionne les doublons, normalise les e-mails et signale les consentements RGPD à vérifier.'] },
      { h: 'Pipeline', l: ['Nouveau : 10 %', 'Qualifié : 25 %', 'Proposition : 50 %', 'Négociation : 75 %', 'Gagné : 100 % · Perdu : 0 %'], p: ['Chaque colonne affiche son nombre d’affaires et son montant total.'] },
      { h: 'Qualification et relances', p: ['L’agent Qualification note chaque nouveau contact (source, organisation, territoire, consentement) et planifie un rappel sous 24 h pour les plus prometteurs. L’agent Relances repère les affaires sans activité depuis 7 jours et rédige l’e-mail de relance, soumis à validation.'] }
    ] },
  { id: 'crm-validations', titre: 'CRM : validations, campagnes et e-mails', espaces: ['admin', 'crm'], ecrans: ['home', 'campaigns'], motscles: 'validation approuver refuser e-mail campagne newsletter récap du lundi viking autonome',
    resume: 'Aucun e-mail ne part sans la validation d’un membre de l’équipe.',
    sections: [
      { h: 'Validations', p: ['Les e-mails préparés par les agents et le Viking (relances, offres de fidélisation, rappels de paiement, campagnes) attendent dans « Aujourd’hui ». Un membre de l’équipe les relit puis les approuve ou les refuse.'] },
      { h: 'Le Viking : validation ou autonome', p: ['En mode « Validation », le Viking propose les changements. En mode « Autonome », il fait avancer les affaires seul ; les e-mails, les campagnes et le passage en Gagné ou Perdu restent soumis à validation.'] },
      { h: 'Récap du lundi', p: ['Chaque lundi, l’agent Campagnes prépare le brouillon du « Récap du lundi » pour les contacts consentants et demande une relecture.'] }
    ] },
  { id: 'crm-instagram', titre: 'CRM : calendrier Instagram et visuels de l’Atelier', espaces: ['admin', 'crm', 'atelier'], ecrans: ['insta', 'atelier'], motscles: 'instagram publication calendrier légende hashtag visuel atelier drakkar à valider programmé publié échec',
    resume: 'Préparer, valider et programmer les publications Instagram.',
    sections: [
      { h: 'Statuts', l: ['Idée.', 'À compléter : un élément manque (texte entre crochets, visuel).', 'À valider : prête, en attente d’un membre de l’équipe.', 'Prêt ou programmé : part à l’heure prévue.', 'Publié, refusé ou échec.'] },
      { h: 'Visuels de l’Atelier', p: ['« Envoyer dans Drakkar » depuis l’Atelier crée une publication avec le visuel et sa légende. Pour la modifier, retouchez le visuel dans l’Atelier puis renvoyez-le. Avant l’envoi, l’Atelier vérifie les droits « réseaux sociaux » des photos utilisées.'] }
    ] },
  { id: 'crm-finance', titre: 'CRM : devis, factures et contrats partenaires', espaces: ['admin', 'crm'], ecrans: ['invoices', 'contracts'], motscles: 'devis facture numérotation paiement échéance retard rappel recouvrement contrat partenaire renouvellement échu',
    resume: 'Le suivi des encaissements et des renouvellements.',
    sections: [
      { h: 'Devis et factures', p: ['La numérotation est chronologique et continue par année, comme l’exige la loi ; les mentions légales viennent des Paramètres. Les documents se copient en texte pour être envoyés depuis votre messagerie ou votre logiciel de facturation.', 'L’agent Recouvrement passe en retard les factures dont l’échéance est dépassée, prépare les rappels (3 au plus, tous les 15 jours) et relance les devis sans réponse depuis 10 jours.'] },
      { h: 'Contrats partenaires', p: ['45 jours avant la fin de chaque contrat, l’agent Renouvellements prépare la relance et une tâche ; un contrat dépassé passe en « échu ».'] }
    ] },
  { id: 'crm-agents', titre: 'CRM : agents autonomes, le Viking et journal de bord', espaces: ['admin', 'crm'], ecrans: ['agents', 'viking', 'journal', 'tasks', 'agenda', 'team'], motscles: 'agent automatisation pause lancer viking ia mission journal de bord briefing répartiteur agenda tâches équipe',
    resume: 'Mettre en pause ou lancer les agents, confier une mission au Viking, suivre le journal.',
    sections: [
      { h: 'Les agents', p: ['Douze agents tournent sur le serveur : Qualification, Relances, Fidélisation, Qualité des données, Vigie des retards, Renouvellements, Recouvrement, Agenda, Répartiteur, Briefing, Campagnes et Instagram. Chaque carte indique sa cadence et sa dernière action ; l’interrupteur le met en pause, « Lancer maintenant » l’exécute tout de suite.'] },
      { h: 'Organisation', p: ['L’agent Agenda crée une tâche de préparation avant chaque rendez-vous et une tâche de compte rendu après. Le Répartiteur attribue les tâches, affaires et contacts sans responsable au membre disponible le moins chargé, selon son rôle. Le Briefing rédige chaque matin le point du jour.'] },
      { h: 'Le Viking', p: ['L’assistant IA du CRM raisonne sur l’ensemble des données, agit avec ses outils et rédige un compte rendu. Il n’est disponible que si une clé d’IA est configurée sur le serveur.'] },
      { h: 'Journal de bord', p: ['Chaque action des agents, du Viking, du site et de l’équipe y est inscrite avec son auteur et son heure.'] }
    ] },
  { id: 'atelier-titres', titre: 'Atelier : titres, chartes et reprise d’une création', espaces: ['atelier'], ecrans: ['atelier', 'atelier-titres'], motscles: 'atelier titre charte couleurs reprendre création modèles',
    resume: 'Chaque création appartient à un titre ; une création d’un autre titre se reprend à vos couleurs.',
    sections: [
      { h: 'Les titres', p: ['Casa Besports, La Gazette du Cotentin, un programme de match… Chaque titre a sa charte : couleurs d’encre, de fond et d’accent, police des titres.'] },
      { h: 'Reprendre une création', p: ['« Mes créations » liste les créations enregistrées de tous les titres, toutes dates. Ouvrez celle d’un autre titre puis « Appliquer la charte du titre » : textes, fonds et accents prennent les couleurs et la police de votre titre.'] }
    ] },
  { id: 'atelier-series', titre: 'Atelier : séries et héritage des visuels', espaces: ['atelier'], ecrans: ['atelier', 'atelier-series'], motscles: 'série héritage bouclée verrouillé dissocier agenda résultats',
    resume: 'Repartir de la création bouclée de la semaine précédente, visuel par visuel.',
    sections: [
      { h: 'Boucler et hériter', p: ['Une création enregistrée dans une série (« Agenda du week-end », « Résultats »…) peut être bouclée. « Nouvelle édition de la série » crée la suivante : chaque visuel est hérité, verrouillé tant qu’il reste identique, et suit les corrections de la création source.'] },
      { h: 'Dissocier', p: ['« Dissocier ce visuel » le rend modifiable, en partie ou en totalité.'] }
    ] },
  { id: 'atelier-zones', titre: 'Atelier : zones réservées et ajustement automatique', espaces: ['atelier'], ecrans: ['atelier', 'atelier-zones'], motscles: 'zone réservée logo partenaire score élément fixe ajuster texte ranger automatiquement',
    resume: 'Réserver la place d’un logo ou d’un score, ranger les calques et caler les textes.',
    sections: [
      { h: 'Zones réservées', p: ['« Réserver une zone » pose un emplacement nommé (logo partenaire, score, météo, QR code…) avant d’avoir l’élément. Livrez l’élément une fois dans « Éléments fixes » : toutes les zones de ce nom se remplissent, dans toutes les créations.'] },
      { h: 'Ranger automatiquement', p: ['Les calques de texte, de logo et de photo se rangent dans la zone de sécurité du format, du titre au pied de page ; les calques verrouillés et les fonds restent en place.'] },
      { h: 'Ajuster les textes', p: ['« Ajuster automatiquement » réduit la taille d’un texte jusqu’à ce qu’il tienne dans sa hauteur, sans passer sous 24 pixels.'] }
    ] },
  { id: 'atelier-symbole', titre: 'Le symbole BE+ : la variante du logo', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'symbole BE+ variante logo petit format icône onglet favicon avatar photo de profil broderie bonnet mug charte',
    resume: '« BE+ » : les capitales et le « + » du logo, en blanc sur un carré noir, pour les petits formats.',
    sections: [
      { h: 'Ce que c’est', p: ['Le symbole reprend les capitales League Spartan et le « + » du logo CASA BESPORTS +, en blanc sur un carré noir. C’est la forme courte de la marque : même famille, même noir et blanc.'] },
      { h: 'Quand l’utiliser', l: ['Là où le logo complet ne se lit plus : icône d’onglet du navigateur, photo de profil, coin d’un visuel, petits objets (bonnet, mug, stylo), broderie.', 'L’un ou l’autre : jamais à côté du logo complet.', 'Toujours sur son carré noir, jamais recoloré ni redessiné ; taille minimale 16 px à l’écran, 8 mm à l’impression.'] },
      { h: 'Dans l’Atelier', l: ['« Ajouter › BE+ Symbole » le pose en haut à droite du visuel ; la forme « Symbole BE+ » du calque Logo transforme un logo déjà posé.', 'Le gabarit « Le symbole BE+ » (Bandeau Casa) existe sur photo, sur fond noir et sur fond blanc.', 'Studio Boutique : « Symbole BE+ » (carré noir) ou « Symbole BE+ (lettres) », qui prend l’encre la plus lisible sur chaque coloris.', 'La charte (« Le bandeau ») le présente avec ses règles.'] },
      { h: 'Sur le site et l’application', p: ['Il sert d’icône d’onglet du navigateur et d’icône de l’onglet Accueil dans la barre du bas, signe les articles relus par la rédaction, ouvre l’application juste avant le logo et figure en pied de page.'] }
    ] },
  { id: 'atelier-synchro', titre: 'Atelier : retrouver son travail sur le PC et le mobile', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'synchro synchronisation reprendre continuer mobile téléphone pc ordinateur tablette appareil travail en cours sauvegarde enregistrement automatique',
    resume: 'Le travail commencé sur un appareil se retrouve sur l’autre : « Reprendre ici ».',
    sections: [
      { h: 'Comment ça marche', p: ['Chaque modification part quelques secondes plus tard dans votre espace : la partie privée de l’Atelier liée à votre compte sur claude.ai, ou votre compte de l’équipe sur casabesports.fr. Ouvrez l’Atelier sur l’autre appareil avec le même compte : le bandeau « Travail plus récent sur … » propose « Reprendre ici ».'] },
      { h: 'Ce qui suit votre travail', l: ['Les visuels, leurs textes et réglages, le Studio Match, le montage du Studio Vidéo et les réglages du studio photo.', 'Les photos importées utilisées par le travail, avec leur légende, leur crédit et leurs droits.', 'L’article en cours du Studio Boutique et le brouillon du Studio Presse.', '« Mes créations », « Mes citations » et les préréglages photo.', 'Les vidéos importées restent sur l’appareil qui les a importées : réimportez-les sur l’autre appareil si besoin.'] },
      { h: 'Sans écraser', l: ['Chaque appareil a son propre emplacement : aucun n’écrase le travail d’un autre.', 'Après une reprise, « Synchro › Revenir à ma version d’avant la reprise » rétablit le travail d’ici.', '« Plus tard » masque le bandeau jusqu’à la prochaine modification sur l’autre appareil.', 'Un appareil qui a seulement ouvert l’Atelier, sans rien modifier, n’est jamais proposé.', 'Sur iPhone, le navigateur peut tout oublier d’une ouverture à l’autre : l’Atelier retrouve alors tout seul la dernière session de l’appareil, au lieu d’ouvrir un nouvel emplacement.'] },
      { h: 'Le bouton « Synchro »', l: ['Carré plein : à jour en ligne. Carré vide : modifications à envoyer. Carré rouge : envoi en pause, le motif est indiqué dans la fenêtre.', 'La fenêtre permet de renommer l’appareil, de couper l’envoi automatique, d’envoyer tout de suite et de retirer un ancien appareil. Les sessions plus anciennes d’un même appareil sont regroupées et se retirent d’un coup.', 'Hors de votre compte (fichier ouvert sur l’ordinateur), le travail reste sur l’appareil : « Exporter… › Projet Atelier (.json) », puis « Ouvrir un projet (.json) » sur l’autre.'] }
    ] },
  { id: 'atelier-logos', titre: 'Atelier : tous les logos en PNG', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'logo logos png télécharger bandeau logotype icône symbole BE+ transparent haute définition kit 4096',
    resume: 'Toutes les versions du logo, dont le symbole BE+, en PNG nets de 512 à 4096 px.',
    sections: [
      { h: 'Où', p: ['Bouton « Logos » en haut de l’Atelier, et « Toutes les versions du logo (PNG) » dans le panneau d’un calque Logo.'] },
      { h: 'Les versions', l: ['Logo bandeau, icône carrée et symbole BE+ : sur leur noir.', 'Logotype blanc ou noir, BE+ lettres blanches ou noires : à fond transparent, pour une photo, un fond sombre ou un fond clair.'] },
      { h: 'Télécharger ou poser', l: ['« PNG » sous chaque version, à la largeur choisie (512 à 4096 px).', '« Tout en PNG : 512, 2048 et 4096 px » : un dossier compressé avec toutes les versions aux trois tailles et un mode d’emploi.', '« Ajouter au visuel » pose la version sur le visuel en cours.'] },
      { h: 'Règles', p: ['Le logo et le symbole ne se recolorent pas et ne se posent pas côte à côte. Détails dans la Charte DA.'] }
    ] },
  { id: 'atelier-lisibilite', titre: 'Atelier : rendre l’écriture lisible sur une photo', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'lisibilité lisible contraste texte écriture grain voile bande zone verre dépoli flou vignette assombrir photo gabarit',
    resume: 'Grain, voiles, zone ou verre dépoli sous les textes, à la main ou en un clic, en mode Gabarit comme en mise en page libre.',
    sections: [
      { h: '✦ Rendre les textes lisibles', p: ['L’Atelier repère chaque texte posé sur la photo, mesure son contraste à l’endroit le plus défavorable et pose dessous ce qu’il faut : voile en bas ou en haut, zone ou verre dépoli au milieu. Rien ne passe jamais sur les lettres.'] },
      { h: 'En mode Gabarit', l: ['Section « Lisibilité du texte », sous les textes du gabarit : grain photo (fin, moyen, gros), voile en bas, voile en haut, zone sous le texte (voile uni ou verre dépoli, position et hauteur).', '« Plus de réglages » : hauteur des voiles, assombrir la photo, vignette, voiles noirs (texte clair) ou blancs (texte foncé).', 'Le gabarit reste modifiable ; « Déplacer les éléments » transforme ces traitements en calques.', 'Quand la photo ne remplit pas tout le cadre (texte déjà sur un aplat), passez par « Déplacer les éléments ».'] },
      { h: 'En mise en page libre', l: ['« Ajouter » : ▒ Grain, ◩ Voile, ▬ Bande, ◫ Verre, ◎ Vignette ; chacun se place sous le premier texte et se règle comme un calque.', 'Le grain se règle en taille, en mélange et en intensité (« Opacité »).'] }
    ] },
  { id: 'atelier-fond', titre: 'Atelier : contrôler l’arrière-plan', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'arrière-plan fond couleur dégradé photo floutée transparent luminosité contraste saturation chaleur flou voile vignette noir et blanc cadrage',
    resume: 'Type de fond, photo de fond et réglages appliqués au fond seulement.',
    sections: [
      { h: 'En mode Gabarit', p: ['« Arrière-plan › Réglages de la photo de fond » : luminosité, contraste, saturation, chaleur, flou, voile et sa couleur, vignette, noir et blanc. Textes, aplats et logo du gabarit restent intacts. Le cadrage reste dans « Cadrage de la photo ».'] },
      { h: 'En mise en page libre', l: ['Type : photo, couleur, dégradé (vertical, horizontal, diagonale, halo), photo floutée ou transparent (le PNG garde la transparence).', '« Photo de fond » : choix de la photo, cadrage, zoom ; « Rogner, pivoter ou retourner la photo ».', 'Mêmes réglages que ci-dessus ; « Remettre le fond d’origine » les efface.'] }
    ] },
  { id: 'atelier-citations', titre: 'Atelier : idées de citations dans les gabarits', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'citation citations idée phrase motivation slogan texte gabarit mes citations garder thème',
    resume: 'Des phrases fortes, originales, proposées dans les textes des gabarits et modifiables à volonté.',
    sections: [
      { h: 'Dans un gabarit', p: ['Sous chaque texte qui s’y prête : « 💡 Idée » propose la suivante, « Au hasard » en tire une. « Thème des idées » choisit d’après le gabarit, un thème précis (jour de match, derby, supporters, bénévoles, jeunes, sport féminin, vestiaire, fair-play, retour de blessure, fin de saison, titre, hommage, mots forts) ou « ★ Mes citations ». Le texte reste modifiable comme d’habitude.'] },
      { h: 'Sur un texte en mise en page libre', l: ['La boîte « 💡 Idées de citations » propose idée suivante, précédente ou au hasard ; « ↺ Mon texte » rend le texte d’avant.', '« ★ Garder » range la phrase (même retouchée) dans « Mes citations », qui suivent vos appareils.'] },
      { h: 'Bon à savoir', p: ['Les idées sont écrites pour Casa Besports : aucune n’est attribuée à une personne réelle. Un texte verrouillé ne reçoit pas d’idée.'] }
    ] },
  { id: 'atelier-apercu', titre: 'Atelier : aperçu du rendu et verrous', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'aperçu rendu prévisualisation fil story grille profil zones interface verrou verrouiller cadenas figer bloquer calque clip vidéo photo',
    resume: 'Voir le visuel tel qu’il sera publié, et figer ce qui est terminé.',
    sections: [
      { h: '👁 Aperçu du rendu', l: ['Le visuel exactement comme il sera exporté, sans cadres ni repères : seul, dans le fil Instagram, en story ou dans la grille du profil (vignette 3:4).', '« Zones de l’interface » montre ce que l’application couvre (haut et bas d’une story, recadrage de la vignette).', 'Flèches pour passer d’un visuel à l’autre ; export du visuel ou de tous depuis l’aperçu.', 'Studio Vidéo : « ⛶ Plein écran » pour regarder le montage.'] },
      { h: 'Verrous', l: ['Mise en page libre : le cadenas d’un calque le fige (souris, clavier, panneau, rangement automatique, changement de gabarit) ; « 🔒 Tout verrouiller » fige tout le visuel.', 'Mode Gabarit : un cadenas par texte et un pour la photo et son cadrage ; un élément verrouillé garde sa valeur, même face à « 💡 Idée » ou au texte proposé par l’IA.', 'Studio Vidéo : le cadenas d’un clip fige ses réglages, sa coupe et sa place. Studio Photo : « Figer le développement de cette photo ».', 'Un clic sur le cadenas déverrouille.'] }
    ] },
  { id: 'atelier-styles-insta', titre: 'Atelier : les styles Insta (citations, fonds d’écran, interview, autographe)', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'styles insta citation phrase texte condensé noir blanc fond d’écran téléphone écran verrouillé interview blason devise sous-titre autographe signature manuscrite gothique souligné papier manuscrit dégradé',
    resume: '42 styles entièrement modifiables, dont les nouveaux : Mot d’ordre, Fond d’écran, Paroles, Autographe.',
    sections: [
      { h: 'Où les trouver', p: ['« Parcourir les gabarits › Styles Insta ». Chaque élément (texte, photo, surface, téléphone, blason, signature) se sélectionne et se modifie directement sur l’image ; un double-clic sur un texte permet de l’écrire sur place.'] },
      { h: 'Les nouveaux styles', l: ['Mot d’ordre : une phrase courte en capitales condensées, seule sur le noir, le blanc ou une photo assombrie ; le texte se resserre tout seul pour tenir.', 'Fond d’écran : pensé pour l’écran verrouillé du téléphone (format Story 9:16), le texte sous l’horloge ; « Fonds d’écran · présentation » les montre sur deux téléphones avec un titre et deux étiquettes.', 'Paroles · interview : la photo de la personne, un blason gravé (devise, initiales et lauriers modifiables), un titre espacé, la signature et le sous-titre.', 'Autographe : la signature en grand, sur une photo ou sur le noir, avec le nom et un message.', 'Variantes : Affiche légende « Ciel clair » (titre minuscule en dégradé), Phrase manuscrite « Papier gris », Portrait citation « En-tête gothique » (mot souligné).'] },
      { h: 'Votre signature', l: ['« Ajouter › ✍ Signature » : choisissez une photo ou une capture de votre signature, sur fond uni. L’Atelier garde le trait seul, sans le fond, et la remet à l’horizontale si elle a été signée en hauteur.', 'Blanche, noire ou de la couleur choisie ; « ↻ Tourner d’un quart » si elle n’est pas dans le bon sens.', 'Une fois importée, elle signe automatiquement les styles « Paroles » et « Autographe » ; elle n’apparaît pas dans « Mes photos ».'] },
      { h: 'Effets de texte', p: ['Dans le panneau d’un texte : « Mots mis en avant » en surligneur, pavé inversé, couleur, dégradé doré, souligné ou italique ; « Texte en dégradé » (deux couleurs). Les idées de phrases (💡) proposent le thème « Mental et discipline » pour ces styles.'] }
    ] },
  { id: 'atelier-premium', titre: 'Atelier : le thème Premium (carrousels éditoriaux)', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'premium carrousel carousel couverture date clé phrase choc chiffre citation chronologie points clés profil résultat score question fin chapitre interview accent corail or blanc clair pseudo numéro de page flou grain suite histoire club be+ be plus bandeaux une variante casa besports magazine league spartan mulish noir et blanc',
    resume: '14 diapos de carrousel éditorial en 6 versions, dont BE+ Bandeaux et BE+ Une à la DA Casa Besports + ; la suite du carrousel et la variante de tout le carrousel en un clic.',
    sections: [
      { h: 'Les diapos', p: ['« Parcourir les gabarits › Premium » : couverture, date clé, phrase-choc, photo et récit, chiffre clé, citation, chronologie, points clés, profil, résultat, question, fin de carrousel, chapitre et interview. Chacune existe en Corail, Or, Blanc (fond sombre), Clair (fond clair, texte noir), BE+ Bandeaux et BE+ Une.'] },
      { h: 'Les variantes BE+ (DA Casa Besports +)', l: ['BE+ Bandeaux : la photo reste visible ; titres en capitales League Spartan dans des bandes blanches, surtitres en étiquettes, deuxième voix soulignée ; symbole BE+ et pseudo en tête de page.', 'BE+ Une : page blanche façon magazine ; logo CASA BESPORTS + en tête, photo cadrée aux repères « + » qui s’arrête toujours au-dessus du texte, grandes capitales noires. Les diapos sans photo deviennent des pages de texte.', 'Noir et blanc, coins droits, Mulish pour les textes longs ; le rouge reste réservé au direct. Sur une diapo de texte, la phrase forte prend la plus grande taille qui tient, sur des lignes équilibrées.', 'Le logo et le symbole sont posés tels quels : jamais recolorés, jamais côte à côte.'] },
      { h: 'Le style des versions Corail, Or, Blanc et Clair', l: ['Photo en noir et blanc, nette ou très floutée, avec du grain ; pseudo en haut à gauche, numéro de page en haut à droite.', 'Surtitre en capitales de couleur, texte en grotesque serrée (Inter Tight), relance en italique serif (Instrument Serif).', 'Espaces insécables posés tout seuls avant « ? ! : ; » et dans « … » : le signe ne part jamais seul à la ligne.'] },
      { h: 'Le bloc de texte', l: ['Les textes du bas forment un bloc : quand un texte s’allonge, le bloc monte et les écarts restent les mêmes.', 'Glisser un des textes déplace tout le bloc. Panneau « Espacements » : écart au-dessus et en dessous de chaque texte, ou « Garder dans le bloc » à décocher pour le libérer.', 'En BE+ Une, la photo cadrée suit le bloc ; si vous changez sa hauteur à la main, elle reste où vous l’avez mise.'] },
      { h: 'Tout le carrousel en une fois', l: ['« Variante · tout le carrousel » : Premium sombre, Premium clair, BE+ Bandeaux ou BE+ Une sur toutes les diapos Premium et partenaires, textes conservés.', 'Panneau « Carrousel Premium » : la couleur d’accent (versions Corail, Or, Blanc et Clair), le pseudo et le format du numéro de page (01 / 06, 1/6, 01…) changent sur toutes les diapos ; flou et grain de la photo de la diapo.', '« Suite du carrousel » : Récit (6), Histoire d’un club (7), Portrait de joueur (6) ou Avant / après match (6). Les diapos s’ajoutent après celle-ci, avec vos photos importées.', 'Le numéro de page suit la place de la diapo et le nombre de diapos. « Ajouter › N° de page » le pose aussi sur n’importe quel visuel.'] },
      { h: 'En story', p: ['En 9:16, le pseudo et le bloc de texte se placent hors des zones couvertes par l’interface d’Instagram ; ils s’y replacent aussi quand on change de format, comme la tête de page et la photo cadrée des variantes BE+.'] }
    ] },
  { id: 'atelier-partenaires', titre: 'Atelier : gabarits partenaires (placements de produits)', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'partenaire partenaires sponsor sponsoring placement produit publicité collaboration commerciale concession automobile voiture garage restaurant brasserie entreprise commerce offre code promo jeu concours logo mur présenté par co2 sedéplacermoinspolluer mention',
    resume: '12 gabarits pour vos partenaires (concessions, restaurants, entreprises), remplis par leur fiche, avec les mentions obligatoires.',
    sections: [
      { h: 'Les gabarits', p: ['« Parcourir les gabarits › Premium · Partenaires », en version sombre, claire, BE+ Bandeaux ou BE+ Une : présenté par, nouveau partenaire, véhicule à la une, portes ouvertes, la table du match, soirée match, portrait d’entreprise, offre partenaire, jeu-concours, nos partenaires (mur de logos), joueur du match présenté par, infos pratiques. « Suite du carrousel » propose des parcours tout faits : concession, restaurant, entreprise, sponsor d’une rubrique.'] },
      { h: 'La fiche du partenaire', l: ['Panneau « Partenaire › ＋ Fiche » : nom, activité, adresse, téléphone, site, Instagram, horaires, offre, code promo, couleur et logo.', 'Le logo importé perd son fond uni (blanc le plus souvent) ; « Fond d’origine » le rend. Sa couleur dominante devient l’accent de ses diapos, modifiable.', 'Les gabarits posés ensuite sont déjà remplis ; « Remplir les diapos partenaires » met à jour celles qui existent, sans toucher aux textes que vous avez changés.', 'Sur claude.ai, les fiches et leurs logos suivent vos appareils. Sur casabesports.fr, les commerces partenaires du Réseau apparaissent dans la liste.'] },
      { h: 'Les mentions', l: ['Chaque visuel porte « Collaboration commerciale » (ou « Publicité ») sous le pseudo : le caractère commercial doit se comprendre tout de suite. Sur Instagram, activez aussi le libellé de partenariat rémunéré.', 'Ce qui reste entre crochets « [ … ] » est propre à la publication (modèle, prix, dates, lot…) : « Vérifier les espacements » le signale avant publication, comme une mention ou un logo manquant.', 'Rien n’est inventé : prix, conditions et dates viennent du partenaire.'] },
      { h: 'Publicité automobile', l: ['Bandeau en bas sur au moins 7 % de l’image, avec l’un des trois messages officiels et #SeDéplacerMoinsPolluer ; « Alterner les trois messages » les fait tourner sur le carrousel.', 'Étiquette de classe CO₂ (sept flèches A à G, carré de côté (largeur + hauteur) / 18) pour une voiture précise : saisissez ses émissions, la classe est proposée, vérifiez-la sur la fiche du véhicule.', 'Ces mentions concernent la publicité pour la vente ou la location d’un véhicule ; un simple parrainage (« Présenté par ») n’en a pas besoin.', 'En story, le bandeau se place au-dessus de la zone couverte par l’interface d’Instagram.'] },
      { h: 'Restaurants et jeux-concours', l: ['La publicité pour l’alcool est très encadrée (loi Évin) : les gabarits restaurant n’en montrent pas. Vérifiez avec le partenaire avant d’en faire apparaître.', 'Jeu-concours : le règlement (en bio) précise lot, dates et conditions ; la mention « Instagram n’est ni organisateur ni parrain de ce jeu » est déjà posée.'] }
    ] },
  { id: 'atelier-interview', titre: 'Atelier : interview devant le mur de partenaires', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier', 'atelier-video'], motscles: 'interview itw mur partenaires sponsors logos fond bord terrain zone mixte réaction joueur détouré détourage ia micro casa photomontage vidéo incrustation officiel uefa conférence de presse couleurs d’origine pastille partenaire principal',
    resume: 'Le joueur détouré devant un mur aux logos de vos partenaires, avec le micro Casa : 15 gabarits pour les visuels (dont 3 en mur officiel), et le même rendu en vidéo dans le Studio.',
    sections: [
      { h: 'Les gabarits', l: ['« Parcourir les gabarits › Interview · Partenaires » : interview bord terrain, réaction d’après-match (avec la citation) et zone mixte (mur en biais, flou de profondeur), chacun avec un mur blanc, noir, couleurs, Casa ou officiel.', 'Choisissez d’abord la photo du joueur dans « Mes photos » : le gabarit la détoure sur votre appareil, cadre le visage dans le haut du visuel et pose le micro à côté de la bouche.'] },
      { h: 'Le mur de partenaires', l: ['Touchez le mur pour le régler : style, taille et proportions des cases, écart, rangées décalées, angle, profondeur de champ, lumière, vignettage, bas assombri, décalage.', 'Les logos viennent de vos fiches partenaires (« Tous mes partenaires » suit les fiches). « ＋ Partenaire », « ＋ Logo », « ＋ Casa » et « ＋ Texte » ajoutent une case, ‹ › la déplacent, × la retire, « Mélanger les cases » change l’ordre.', 'Le logo Casa Besports est posé tel quel (version officielle). Des logos de partenaires rémunérés rendent la publication commerciale : la mention « Collaboration commerciale » est posée en haut, gardez-la.'] },
      { h: 'Mur officiel et couleurs d’origine', l: ['Style « Officiel » : le mur des conférences de presse des grandes compétitions. Cases blanches, logos des partenaires à taille égale dans leurs couleurs d’origine, logotype Casa Besports répété ; aucune marque de compétition n’est reproduite.', '« Logos des partenaires : Couleurs d’origine » garde les vraies couleurs dans les autres styles : la case du partenaire passe en blanc (mur Casa) ou le logo se pose sur une pastille blanche (murs noir et couleurs). Le mur reste dans le style Casa Besports.', '« Style du mur » revient aux logos recolorés (blanc, noir ou couleur du partenaire). Un logo ne se recolore que si la charte du partenaire le permet.'] },
      { h: 'Renseigner les partenaires du mur', l: ['« Renseigner les partenaires du mur » : pour chaque fiche, le nom, le nom affiché sans logo, la couleur officielle (code hexadécimal de sa charte), la présence (sur le mur, partenaire principal deux fois plus présent, retiré du mur), le fond de sa case (auto, blanc, noir, couleur officielle) et la version du logo (auto, couleurs d’origine, blanc, noir, nom en toutes lettres).', '« Importer le logo » ou « Changer le logo » : son fond uni est retiré, « Fond d’origine » le rend. « ＋ Partenaire » crée une fiche par son nom : elle s’affiche en toutes lettres jusqu’à l’import du logo.', 'Ce sont les fiches du panneau « Partenaire » : elles servent aussi aux gabarits Premium · Partenaires et suivent vos appareils.'] },
      { h: 'Le joueur', l: ['Taille, position, ombre sur le mur, lumière de contour, noir et blanc, miroir. Une autre photo choisie dans « Mes photos » remplace celle du joueur.', '« Retoucher le détourage » : touchez la personne à garder (le reste disparaît), effacez au pinceau un reste de fond ou une autre personne, restaurez une main ou des cheveux coupés, puis « Valider le détourage ».', 'Le détourage se fait sur l’appareil, la photo n’est envoyée nulle part. Photo de Casa Besports ou dont vous avez les droits (photographe et personne photographiée) ; les photos d’agence ne se détourent pas : pas de photomontage.'] },
      { h: 'Le micro Casa', p: ['Micro de reportage dessiné pour Casa Besports, cube noir ou blanc au symbole BE+. Il se place à côté de la bouche ; glissez-le pour le déplacer, « Placer devant la bouche du joueur » le replace. « ▦ Mur de partenaires », « ✂ Joueur détouré » et « ◉ Micro Casa » s’ajoutent aussi à n’importe quel visuel en mise en page libre.'] },
      { h: 'En vidéo', l: ['Studio Vidéo, un plan sélectionné : « Incrustation · nouveau fond », « Remplacer le fond de ce plan », « Joueur détouré (IA) », puis un « Mur … » dans « Nouveau fond ». Le joueur est détouré image par image, sans fond vert, et lissé d’une image à l’autre.', 'Le mur reprend celui réglé dans l’Atelier (logos, angle, flou…). « Micro Casa devant le joueur » le pose à côté de la bouche dès la première image ; curseurs pour l’ajuster. Le nom se pose avec « Titre » et « Sous-titre » du plan.'] },
      { h: 'Les citations', p: ['Les crochets « [ … ] » restent jusqu’à ce que vous les remplissiez : seules des paroles réellement prononcées par le joueur vont dans la citation.'] }
    ] },
  { id: 'atelier-montage', titre: 'Atelier : montage auto du carrousel', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'montage auto automatique carrousel carousel déposer photos textes gabarits cadrage recadrer visage sujet répartir diapos corriger planche ia premium be+ partenaires',
    resume: 'Déposez photos et textes : l’Atelier monte le carrousel avec les gabarits choisis, cadre les photos et ajuste les textes ; chaque diapo se corrige avant d’être ajoutée ou enregistrée.',
    sections: [
      { h: 'Déposer', l: ['« ✦ Montage auto du carrousel » (panneau de gauche) : glissez vos photos et vos textes (fichiers .txt ou .md), ou collez le texte.', 'Un paragraphe donne une diapo. Sont reconnus : « Surtitre : texte », un score (« 2-1 »), une citation entre « » suivie de son auteur, un chiffre clé, une liste à puces ou de dates, une question, un appel à l’action.'] },
      { h: 'Choisir les gabarits', l: ['« Une suite Premium » : Récit, Histoire d’un club, Portrait de joueur, Avant / après match, ou un parcours partenaire (concession, restaurant, entreprise, sponsor d’une rubrique), en Premium sombre, Premium clair, BE+ Bandeaux ou BE+ Une. « Ma sélection » : « ＋ Choisir des gabarits » pour les cocher un par un dans la bibliothèque.', 'Chaque texte va au gabarit qui garde tout son contenu : un score sur la diapo résultat, une citation sur la diapo citation, un chiffre sur le chiffre clé. Couverture en premier, fin de carrousel en dernier ; une photo restante devient une diapo photo.'] },
      { h: 'Cadrage et textes', l: ['Le sujet de chaque photo (visage, sinon la zone la plus marquante) est placé hors du bloc de texte, avec un léger zoom si besoin.', 'Les textes prennent la plus grande taille qui tient dans leur gabarit ; un texte trop long est réduit jusqu’à tenir sous la photo.'] },
      { h: 'Corriger avant d’enregistrer', l: ['La planche montre toutes les diapos : changez de gabarit (les textes suivent), de photo, touchez l’aperçu pour recentrer la photo sur un point, modifiez chaque texte, déplacez ou supprimez une diapo.', 'Puis « Ajouter au carrousel », « Remplacer le carrousel » ou « Ajouter et enregistrer » (dans Créations). Tout reste modifiable ensuite dans l’Atelier.'] },
      { h: 'L’IA', p: ['Sur claude.ai, ou sur casabesports.fr quand la clé IA est configurée, l’IA répartit les textes dans les gabarits ; sinon les règles intégrées le font. Elle ne reçoit que vos textes et le nombre de photos, jamais les images, et n’invente rien : chaque fait vient de vos textes.'] }
    ] },
  { id: 'atelier-espacements', titre: 'Atelier : les espacements entre textes et images', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier'], motscles: 'espacement espace distance marge alignement aligné magnétisme repère guide écart bord vérifier mise en page commune carrousel diapo position',
    resume: 'Les distances s’affichent pendant qu’on déplace un élément ; le panneau les règle au pixel et vérifie la diapo.',
    sections: [
      { h: 'En déplaçant', l: ['Glissez un texte, une photo ou un logo (souris, doigt ou flèches du clavier) : ses distances aux éléments voisins et aux bords s’affichent en pixels du visuel exporté.', 'Rose : la distance. Vert « = » : égale à un autre espace de la composition. Orange : trop serré ou trop près du bord. Traits bleus : bord ou centre aligné sur un autre élément ou sur le centre du visuel. Violet : les écarts d’un bloc de texte.', 'Les textes se mesurent comme l’œil les voit : du haut des capitales à la ligne de base.', 'Magnétisme : l’élément s’accroche aux alignements, au centre et aux espaces égaux. Maintenez Alt pour le déplacer librement, ou décochez « Magnétisme ».'] },
      { h: 'Le panneau « Espacements »', l: ['Les quatre distances de l’élément sélectionné (au-dessus, en dessous, à gauche, à droite), avec le nom du voisin : tapez une valeur pour le placer au pixel près.', '« À égale distance » le centre entre ses voisins, en hauteur ou en largeur.', 'Dans un cadre (photo, forme), les distances se mesurent jusqu’aux bords du cadre.'] },
      { h: 'Vérifier les espacements', l: ['Signale les éléments presque alignés, les espaces presque égaux, ce qui est trop serré ou se chevauche, trop près du bord ou hors du visuel, ce qui passe sous l’interface d’Instagram (compteur 1/6, icônes du bas, story, vignette du profil) et ce qui n’est pas tout à fait à la même place que sur la diapo précédente.', '« Corriger » ou « Tout corriger » applique les corrections proposées ; « Retour » les annule.'] },
      { h: 'Même mise en page sur les autres diapos', p: ['« Recopier les positions » place les éléments des autres diapos comme sur celle-ci (même nom, même texte comme un pied de page, ou même rang quand les diapos ont la même structure) ; « Positions et styles des textes » recopie aussi police, taille et couleur. Textes et photos ne changent pas.'] }
    ] },
  { id: 'atelier-versions', titre: 'Atelier : versions et recherche des créations', espaces: ['atelier'], ecrans: ['atelier', 'atelier-versions'], motscles: 'version création recherche légende crédit restaurer comparer',
    resume: 'Revenir à une version précédente d’une création, retrouver une création ou une photo.',
    sections: [
      { h: 'Versions', p: ['À chaque enregistrement, l’Atelier garde une version avec sa miniature. « Comparer » montre côte à côte la version et l’état actuel, avec la liste des visuels et textes modifiés ; « Restaurer » la rétablit (l’état actuel est gardé comme version).'] },
      { h: 'Recherche', p: ['La recherche porte sur le nom des créations, leur légende, leurs mots-dièse, les textes des visuels, ainsi que la légende et le crédit des photos.'] }
    ] },
  { id: 'atelier-agence', titre: 'Atelier : photos et vidéos d’agence, droits et durée', espaces: ['atelier'], ecrans: ['atelier', 'atelier-agence', 'atelier-video'], motscles: 'agence afp vidéo studio vidéo durée droits réseaux sociaux',
    resume: 'Importer des contenus d’agence et vérifier les droits avant publication.',
    sections: [
      { h: 'Contenus d’agence', p: ['Avec un compte AFP configuré sur le serveur, « Agence (AFP) » recherche photos et vidéos : la photo rejoint « Mes photos », la vidéo le Studio Vidéo, avec crédit et durée.'] },
      { h: 'Droits réseaux sociaux', p: ['Avant l’export ou l’envoi dans Drakkar, l’Atelier vérifie que chaque photo utilisée est autorisée sur les réseaux sociaux. Une photo « à vérifier » ou « non autorisée » est signalée, et l’envoi demande une confirmation.'] }
    ] },
  { id: 'espace-club', titre: 'L’espace club : raconter la vie de son club', espaces: ['club', 'redaction', 'admin'], ecrans: ['club', 'workflow'], motscles: 'club correspondant bénévole association compte rendu annonce modèle fiche photo mineurs relecture',
    resume: 'Les correspondants des clubs proposent des contenus guidés ; la rédaction relit et publie.',
    sections: [
      { h: 'Rédiger', l: ['« Mon club » : choisissez un modèle (compte rendu de match, annonce ou événement, recherche de bénévoles, résultats du week-end, portrait, agenda des matchs).', 'Remplissez les champs : le titre, le chapeau et le texte se composent tout seuls, l’aperçu montre l’article tel qu’il sera proposé. Le titre reste modifiable.', 'Une photo se joint avec sa description, son crédit et l’attestation d’autorisation (l’accord écrit des parents pour un mineur).'] },
      { h: 'Envoyer', p: ['« Envoyer à la rédaction » verrouille le contenu et le place dans la file de relecture avec le badge « Espace club ». La rédaction publie, demande des corrections (la note s’affiche dans « Mes contenus ») ou ne retient pas le contenu.'] },
      { h: 'La fiche du club', p: ['Présentation, lieu, entraînements, équipes, tarifs, contacts publics et réseaux : la fiche est envoyée pour validation, puis affichée dans l’onglet « Infos club » de la page du club. Côté rédaction : Réseau › Fiches clubs, avec la comparaison champ par champ.'] }
    ] },
  { id: 'reseau-mr', titre: 'Mises en relation avec les commerces et partenariats rémunérés', espaces: ['admin'], ecrans: ['reseau'], motscles: 'commerce mise en relation partenariat sponsor commission facture traçabilité relais contact',
    resume: 'De la demande d’un club ou d’un membre jusqu’au partenariat rémunéré et à sa commission.',
    sections: [
      { h: 'Le circuit', l: ['Un club, un membre ou un visiteur choisit un commerce sur la carte (Territoire › Commerces) et envoie sa demande : elle reçoit une référence MR-AAAA-NNNN.', 'Réseau › Mises en relation : relisez le message proposé (il part tel quel), choisissez le canal, puis « Valider et transmettre » ou « Ne pas transmettre » avec un motif.', 'Par e-mail, l’envoi est réel seulement si un serveur SMTP est configuré ; sinon une tâche « Envoyer l’e-mail » est créée avec le texte. Téléphone, visite et courrier créent une tâche à votre nom.', 'Le commerce ne reçoit jamais les coordonnées du demandeur : il répond à Casa Besports, qui fait les présentations.'] },
      { h: 'Partenariat rémunéré', p: ['Quand le partenariat est signé, indiquez le montant HT, le taux de commission (10 % par défaut) et à qui la commission est facturée : une facture brouillon est créée dans Drakkar et l’affaire passe en « Gagné ». Cochez « Commission encaissée » au paiement : la facture passe en « payée ».'] },
      { h: 'Traçabilité', l: ['Chaque étape est horodatée dans le journal de la demande, avec son auteur.', 'Le demandeur suit les étapes publiques dans Mon espace (sans les notes internes).', 'Le CRM reçoit les contacts (demandeur et commerce), l’affaire, les tâches et la facture.', 'L’export CSV reprend toutes les demandes avec montants et commissions.'] },
      { h: 'Respect des commerces', p: ['Chaque e-mail contient un lien « ne plus être sollicité » ; un commerce peut aussi le demander depuis sa fiche. Il est alors exclu des mises en relation.'] }
    ] },
  { id: 'reseau-annuaire', titre: 'L’annuaire des commerces de Cherbourg-en-Cotentin', espaces: ['admin'], ecrans: ['reseau'], motscles: 'annuaire commerce sirene insee openstreetmap import mise à jour données publiques',
    resume: 'D’où viennent les commerces, comment les mettre à jour, ce qui est conservé.',
    sections: [
      { h: 'Les sources', l: ['INSEE, base SIRENE (API Recherche d’entreprises) : établissements actifs et diffusibles situés à Cherbourg-en-Cotentin, dans les activités de commerce de détail, restauration, hébergement, sport et services de proximité.', 'OpenStreetMap (Overpass) : commerces cartographiés par les contributeurs, avec téléphone, site et horaires quand ils sont renseignés.', 'Les deux sont rapprochés par le nom et la position (moins de 150 m).'] },
      { h: 'Mettre à jour', p: ['Réseau › Annuaire des commerces › « Mettre à jour » (administrateur), ou en ligne de commande. Les ajouts manuels, les retraits, les e-mails saisis et les partenaires sont conservés ; un commerce disparu des sources est retiré, ou masqué s’il a un historique de mises en relation.'], code: 'npm run commerces' },
      { h: 'Ce qui est publié', p: ['Nom, activité, adresse, position, téléphone, site et horaires. Les e-mails ne sont jamais affichés : ils servent uniquement aux mises en relation validées par l’équipe.'] }
    ] },
  { id: 'reseau-cv', titre: 'Certifier un CV « Casa Besports »', espaces: ['admin'], ecrans: ['reseau'], motscles: 'cv certification certificat vérifier sceau qr membre profil révoquer',
    resume: 'Vérifier un parcours, délivrer le certificat, le révoquer.',
    sections: [
      { h: 'Vérifier', l: ['Réseau › Certifications : la demande montre le CV tel que le membre le verra.', 'Cochez chaque vérification : identité, parcours sportif confirmé auprès des clubs cités, diplômes ou attestations vus, photo conforme.', '« Demander un complément » ou « Refuser » exigent un message, visible par le membre.'] },
      { h: 'Le certificat', p: ['Il porte un numéro CB-AAAA-XXXXXX, l’empreinte SHA-256 du contenu certifié et de la photo, et une signature du serveur. Le CV affiche alors le sceau et un QR code menant à la page « Vérifier un certificat ». Si le membre modifie son CV, le sceau tombe jusqu’à une nouvelle demande.'] },
      { h: 'Révoquer, effacer', p: ['« Révoquer » rend le certificat invalide à la vérification. Quand le membre retire sa demande, son dossier est effacé du serveur ; le numéro reste seulement marqué « retiré par son titulaire ».'] }
    ] },
  { id: 'carte-hors-connexion', titre: 'La carte du territoire, en ligne et hors connexion', espaces: ['redaction', 'admin', 'club'], ecrans: ['reseau', 'club'], motscles: 'carte territoire normandie ign osm hors connexion pack zone tuiles zoom',
    resume: 'Les fonds de carte, la carte embarquée et l’enregistrement de zones pour le terrain.',
    sections: [
      { h: 'Les fonds', l: ['Plan IGN et photographies aériennes (Géoplateforme IGN) : jusqu’au niveau de la rue.', 'OpenStreetMap : consultation seulement.', 'Carte embarquée : les 2 644 communes de Normandie, les départements et la côte, toujours disponibles, même sans réseau.'] },
      { h: 'Hors connexion', p: ['Territoire › Hors connexion : choisissez une zone (Cherbourg-en-Cotentin, la Hague, le Nord-Cotentin, la vue affichée ou toute la région), le fond et la précision. La taille est estimée avant le téléchargement (12 000 tuiles au plus). Les zones enregistrées restent sur l’appareil, même après une mise à jour du site.'] }
    ] },
  { id: 'atelier-presse', titre: 'Studio Presse : articles pour La Manche Libre', espaces: ['atelier'], ecrans: ['atelier', 'atelier-presse'], motscles: 'presse article la manche libre correspondant calibrage caractères comptage chapô titre corps intertitre sources à confirmer consignes recherche web correction docx',
    resume: 'Rédiger un article de presse locale à partir d’une saisie minimale, avec un corps compté au caractère près.',
    sections: [
      { h: 'Saisie minimale', p: ['Le sujet (événement, commune ou équipe, date si nécessaire) et le nombre de caractères du corps suffisent : tout pile, au maximum ou dans une fourchette. Ajoutez si besoin l’angle, la rubrique, vos notes, propos recueillis et liens, et vos documents : .txt, .docx, .odt, .pdf, transcriptions .srt, photos lisibles.'] },
      { h: 'Ce que fait l’Atelier', l: ['Claude rédige titre, chapô et corps selon vos consignes (onglet Consignes, reprises mot pour mot).', 'Le code compte le corps comme le script Python des consignes : normalisation NFC, espaces et ponctuation compris, retours à la ligne exclus, intertitres comptés.', 'Si la cible n’est pas atteinte, Claude ajuste le corps (calibrage) ; la ligne « Corps : N caractères… » est toujours écrite par le code, d’après le texte livré.', 'Relecture automatique : texte brut (Markdown, tabulations, caractères invisibles, espaces doubles), formules à éviter, émojis et mots-dièse, intertitres selon la longueur, titre, chapô et attaque distincts, guillemets, répétitions.', 'Sources : seules les sources réellement consultées restent dans « Sources complémentaires » ; les autres sont signalées sous l’article.'] },
      { h: 'Selon l’endroit', l: ['Atelier de casabesports.fr : Claude vérifie et complète en ligne (recherche web, liens de vos notes). Réglages du serveur : ANTHROPIC_API_KEY, PRESSE_MODEL (modèle), PRESSE_RECHERCHE=off (sans recherche).', 'Atelier publié sur claude.ai : Claude rédige avec votre compte, sans recherche web ; ce qu’il aurait vérifié en ligne figure dans « À confirmer ».', 'Sans IA : « Préparer la demande » copie vos consignes et votre saisie ; collez la réponse de Claude dans le champ Titre pour la répartir, la compter et la relire.'] },
      { h: 'Corriger et livrer', l: ['Demander une correction : les faits validés, l’angle et les consignes sont conservés, puis le corps est recalibré.', 'Recalibrer : après une retouche à la main, Claude ramène le corps à la cible sans toucher au titre ni au chapô.', 'Copier la livraison : titre, chapô, corps, puis les lignes « Corps », « Sources complémentaires » et « À confirmer ». Le texte est nettoyé juste avant la copie.', 'Article .docx : titre, chapô et corps seuls, pour un envoi à la rédaction.', 'Mes articles : chaque rédaction est enregistrée avec ses versions (sur le serveur, visibles par vous et l’administrateur ; sinon sur cet appareil).'] }
    ] },
  { id: 'atelier-livre', titre: 'Studio Livre : écrire « L’esprit du football »', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier', 'atelier-livre'], motscles: 'livre écrire écriture chapitre chapitres manuscrit esprit du football un chapitre par jour planning calendrier objectif mots suivi série sprint séance concentration machine à écrire nuit typographie guillemets notes de bas de page annotations relecture versions comparer restaurer fiches personnes clubs sources analyse répétitions lisibilité assistant ia résumé quatrième de couverture export word docx pdf epub markdown import sauvegarde agenda ics',
    resume: 'Un espace d’écriture complet pour un livre de 12 chapitres, un chapitre par jour : planning, objectif de mots, suivi, éditeur typographique, analyse, versions, assistant et exports Word, PDF et EPUB.',
    sections: [
      { h: 'Le planning', l: ['« ✎ Studio Livre », en haut de l’Atelier, ouvre le tableau de bord : le chapitre du jour, l’avancement du livre, les 12 jours du planning et les mots écrits chaque jour.', 'Un chapitre par jour à partir du « Premier jour » ; chaque chapitre peut avoir son propre jour (vue « Plan » ou onglet Chapitre). En cas de retard, « Décaler le planning » redonne un chapitre par jour à partir d’aujourd’hui.', '« Planning (.ics) » ajoute à votre agenda un rendez-vous par chapitre restant, avec un rappel dix minutes avant.'] },
      { h: 'Écrire', l: ['Intertitres, citations, listes, séparateur de scène, gras, italique. La typographie française se fait à la frappe : guillemets « », apostrophe ’, espaces insécables avant ; : ! ?, points de suspension, tiret de dialogue.', '« ⁿ » ajoute une note de bas de page à l’endroit du curseur ; « ✎ » annote un passage pour la relecture ; « Typo » corrige la typographie de tout le chapitre ; « ▦ » envoie l’extrait choisi au montage carrousel.', 'Concentration (« ◎ », Échap pour revenir) : la ligne en cours reste au milieu de l’écran, seul le paragraphe en cours reste en pleine lumière. Mode nuit (« ◐ »), police et taille du texte.', 'Tout s’enregistre au fil de l’écriture. Ctrl+F cherche, Ctrl+Maj+F passe en concentration.'] },
      { h: 'Le suivi', l: ['Mots du jour, temps d’écriture, jours d’affilée, séances, sprints de 10 à 45 minutes avec un objectif. « Chapitre terminé » coche la journée et propose le chapitre suivant.', 'Note du jour ; pour chaque chapitre : intention, points clés à cocher, résumé, sources et faits à vérifier (cochés une fois vérifiés).'] },
      { h: 'Analyse, versions, fiches', l: ['Analyse du chapitre : phrases longues, répétitions rapprochées, adverbes en -ment, débuts de phrases répétés, formules toutes faites, mots fréquents, lisibilité. Touchez une ligne pour la surligner dans le texte.', 'Versions : instantanés automatiques (à l’ouverture, toutes les dix minutes d’écriture, avant chaque correction ou remplacement), comparaison mot à mot, restauration.', 'Fiches : personnes, clubs, lieux, matchs et thèmes du livre, avec les chapitres où ils sont cités. Chercher et remplacer dans le chapitre ou dans tout le livre, sans tenir compte des accents.'] },
      { h: 'L’assistant', p: ['À votre demande seulement, le texte du chapitre part à Claude, et rien d’autre : relecture, style, résumé, questions d’éditeur, plan d’après vos notes, faits à vérifier, titres, cohérence entre chapitres, quatrième de couverture. Il propose, vous acceptez une à une ; une proposition qui ajoute un chiffre ou un nom est signalée et n’est jamais acceptée d’office. Il n’ajoute aucun fait, aucun nom, aucune citation.'] },
      { h: 'Exporter, importer, retrouver', l: ['Word (.docx : styles, notes de bas de page, numéros de page, sommaire, annotations en commentaires si vous le demandez), PDF (manuscrit A4 ou livre A5), EPUB avec couverture, Markdown, texte, et sauvegarde complète (.json).', 'Import d’un fichier Word, Markdown, texte ou d’une sauvegarde : ajout, remplacement, ou répartition dans les chapitres (un titre de niveau 1 = un chapitre). Une version d’avant est toujours gardée.', 'Le livre vous suit d’un appareil à l’autre : sur claude.ai dans votre espace privé, sur casabesports.fr avec votre compte. Si un chapitre a changé aux deux endroits, celui de l’appareil est gardé et l’autre version est dans Versions.'] }
    ] },
  { id: 'atelier-boutique-5d', titre: 'Studio Boutique : la vue 5D', espaces: ['atelier'], ecrans: ['atelier-boutique'], motscles: '5d 3d volume rotation 360 vidéo réalité augmentée ar usdz glb gltf iphone ipad android boutique en ligne maquette tourner zoomer mouvement tissu échelle réelle',
    resume: 'L’article en volume, à l’échelle réelle : on le tourne, il bouge, il s’exporte en images, en vidéo 360° et en modèles 3D pour la réalité augmentée.',
    sections: [
      { h: 'Les cinq dimensions', l: ['1 · 2 · 3 : largeur, hauteur, profondeur. L’article en 3D, aux dimensions du support (textiles : taille M environ).', '4 : le mouvement. Rotation de présentation, tissu qui ondule, vidéo 360°.', '5 : chez vous. Réalité augmentée à taille réelle (USDZ sur iPhone et iPad, GLB sur Android et le web).'] },
      { h: 'Dans le studio', l: ['Bouton « 5D » en haut du Studio Boutique. Glissez pour tourner, molette ou pincement pour zoomer, double-clic pour recentrer, flèches du clavier ; Échap revient au studio.', 'Points de vue : face, 3/4, profil, 3/4 dos, dos, plongée. Coloris, lumière (studio, jour, soirée) et fond (studio clair ou sombre, blanc, noir, transparent).', 'Textiles, sacs et écharpe : la maquette de face devient un volume, celle de dos habille l’arrière. Objets : leurs formes exactes, avec la matière (céramique, verre, plastique, inox, tissu) et le marquage.'] },
      { h: 'Exports', l: ['Images HD : six angles en PNG 2 048 px (fond transparent possible).', 'Rotation 360° : 36 images JPEG, une tous les 10°, pour les visualiseurs 360° des boutiques en ligne.', 'Vidéo 360° : MP4 de 8 secondes (carré, 4:5, story ou 16:9), avec le nom de l’article et le logo Casa si vous le souhaitez.', 'Modèle 3D GLB (glTF 2.0, en mètres) : web, Android et boutiques en ligne qui acceptent la 3D. USDZ : ouvert sur iPhone ou iPad (Fichiers, Mail, Messages), l’article apparaît dans la pièce, à taille réelle.', '« Dossier 5D complet » réunit tout dans une archive, avec un mode d’emploi.'] },
      { h: 'Bon à savoir', p: ['Tout est calculé sur l’appareil : la création n’est envoyée nulle part. Les volumes sont simplifiés (ni patronage ni simulation de tissu) : validez coupe, couleurs et marquages sur un prototype avant la production.'] }
    ] },
  { id: 'atelier-boutique-promo', titre: 'Studio Boutique : formats promo et dossier export', espaces: ['atelier'], ecrans: ['atelier-boutique'], motscles: 'promo promotion lancement story coloris bannière packshot visuel produit fond blanc line sheet fiche catalogue revendeur export b2b douane code sh hs composition grammage origine moq prix de gros mesures',
    resume: 'Les visuels d’un lancement dans la charte Casa, et la fiche catalogue bilingue pour les revendeurs et l’export.',
    sections: [
      { h: 'Les formats', l: ['Bouton « Promo » du Studio Boutique : lancement (4:5), story (9:16), coloris (carré), face et dos, détail du marquage, bannière du site (2 400 × 1 000), visuel produit sur fond blanc pour chaque coloris (2 000 × 2 000), fiche catalogue PDF.', 'Titre, accroche, appel à l’action et prix affiché se règlent une fois ; fond blanc, noir ou studio ; visuels de la maquette ou de la vue 5D.', '« Exporter les formats » les télécharge ; « Envoyer à l’Atelier » les ajoute à Mes photos, pour les poser dans un gabarit avec la mention et la légende.'] },
      { h: 'Dossier export (B2B)', l: ['Référence, composition, grammage, pays de fabrication, code SH (douane), poids, entretien, conditionnement, délai, minimum de commande, prix de gros HT, fournisseur, et le tableau des mesures par taille.', 'Rien n’est inventé : ce qui reste vide s’imprime « à renseigner ». Le prix de gros proposé (la moitié du prix de vente HT, jamais sous le coût de revient) suit le barème indicatif, modifiable.', 'Sorties : fiche catalogue (A4 paysage, français-anglais), tableau produit (CSV, une ligne par coloris et par taille) et une page export bilingue ajoutée à la fiche technique.'] }
    ] },
  { id: 'atelier-boutique-commande', titre: 'Studio Boutique : commandes personnalisées', espaces: ['atelier'], ecrans: ['atelier-boutique'], motscles: 'commande personnalisée club équipe entreprise liste nominative nom numéro taille flocage devis bon de commande bat bon à tirer production marquage étiquettes colisage acompte remise',
    resume: 'Pour un club ou une entreprise : la liste nominative, le prix, le devis, le bon à tirer et les fichiers de production pièce par pièce.',
    sections: [
      { h: 'La liste', l: ['Bouton « Commande perso » du Studio Boutique, à partir de l’article ouvert. Une ligne par pièce : nom, numéro, taille, quantité, coloris, remarque.', '« Coller depuis un tableur » accepte les colonnes copiées d’Excel, Numbers ou Google Sheets (Nom, Numéro, Taille, Quantité) ; « Importer » lit un CSV ; « Modèle à remplir » en fournit un.', 'Contrôles : tailles absentes de l’article, quantités, numéros en double, noms trop longs. Maillots : nom et numéro au dos (et devant si prévu). Autres articles : écrivez {NOM} ou {NUMERO} dans un calque texte pour le personnaliser.'] },
      { h: 'Le prix', p: ['Prix unitaire HT et supplément de personnalisation proposés d’après le barème (indicatif, modifiable) pour la quantité commandée ; remise, livraison, TVA et acompte se règlent ; le coût de revient estimé reste affiché.'] },
      { h: 'Les documents', l: ['Devis et bon de commande (PDF), bon à tirer avec chaque pièce et un cadre « Bon pour accord » (PDF), fichier de production (CSV), fichiers de marquage à 300 dpi pièce par pièce, étiquettes de colisage (PDF A4, 24 par page), ou tout dans une archive.', 'Les mentions du vendeur (SIRET, TVA, conditions, paiement) se saisissent une fois dans « Vendeur » ; vides, elles s’impriment « à renseigner ».', 'L’Atelier n’envoie rien : transmettez vous-même les documents au client.'] },
      { h: 'Suivi et données', l: ['Statuts : devis, BAT envoyé, validée, en production, expédiée, livrée, annulée. « Mes commandes » les retrouve.', 'Les commandes restent sur l’appareil ; elles suivent aussi votre compte sur claude.ai (espace privé) et, sur la plateforme, l’équipe. Noms et coordonnées servent uniquement à la commande : supprimez-la une fois livrée.'] }
    ] },
  { id: 'atelier-match-styles', titre: 'Studio Match : les styles Casa Besports', espaces: ['atelier'], ecrans: ['atelier'], motscles: 'studio match habillage score png visuel style casa or noir blanc be+ symbole tv diffusion bandeau vidéo planche comparer export zip thème couleurs clubs champagne',
    resume: 'Tous les habillages du match dans la DA Casa Besports : noir, blanc et or, signés du symbole BE+, en six styles réglables.',
    sections: [
      { h: 'Les six styles', l: ['Noir & or : fond noir ; scores, filets et onglets en or.', 'Blanc & or : fond blanc, lettres noires, or profond.', 'Or & noir : fond or métal, lettres et symbole noirs.', 'Bandeaux : les titres sur des bandes blanches, comme le logo ; la photo du match reste en couleur.', 'Photo noir et blanc : la photo du match en plein cadre, en noir et blanc, rehaussée d’or.', 'Noir & blanc : la charte stricte, sans or.'] },
      { h: 'Dans le Studio Match', l: ['« Styles Casa Besports » montre les six rendus côte à côte. Un clic applique le style à tous les habillages du match : visuels, écran TV, Diffusion TV et vidéo du match.', 'Réglages : teinte de l’or (or métal, champagne, vieil or), symbole BE+ (sur son carré noir ou lettres seules), couleurs des équipes (or, noir et blanc, ou couleurs des clubs), chiffres du score (en or, ou blanc ou noir).', '« Comparer » choisit l’habillage montré. « Planche des 6 styles » l’exporte en une image PNG ; « Cet habillage dans les 6 styles » en archive ZIP, en vertical et en horizontal.'] },
      { h: 'La charte', l: ['Le symbole BE+ signe ces habillages à la place du logo complet : posé tel quel, jamais recoloré, jamais à côté du logo complet.', 'Les titres restent noirs ou blancs ; l’or rehausse ; le rouge reste réservé au direct.', 'Capitales League Spartan, textes en Mulish, coins droits. Les bandeaux TV restent sur fond noir pour se lire sur n’importe quelle image.'] },
      { h: 'Bon à savoir', p: ['Les anciens thèmes (Vitrine, Diffusion TV, Couleurs des clubs, Clair) restent dans la liste « Thème ». Les matchs qui utilisaient l’ancien thème Vitrine passent au style Noir & or. Vérifiez scores, noms et horaires avant publication.'] }
    ] },
  { id: 'atelier-photo', titre: 'Studio Photo : développer une photo comme un pro', espaces: ['atelier'], ecrans: ['atelier', 'atelier-photo'], motscles: 'studio photo développement raw tiff 16 bits exposition courbes tsl balance blancs netteté bruit recadrer redresser perspective masque correcteur lut préréglage export',
    resume: 'Retoucher et étalonner une photo en pleine définition, sans abîmer l’original.',
    sections: [
      { h: 'Ouvrir', l: ['Bouton « Studio Photo » de l’en-tête, ou le petit rond sur une photo de « Mes photos ».', 'Formats : JPEG, PNG, WebP, AVIF, TIFF 8 et 16 bits (convertis sans perte), HEIC selon le navigateur, et les fichiers RAW des appareils photo (Canon, Nikon, Sony, Fujifilm, Panasonic, Olympus, Pentax, DNG…) à partir de l’aperçu JPEG qu’ils contiennent.', 'L’original est toujours conservé : chaque réglage reste modifiable, et « Enregistrer dans Mes photos » crée une copie qui garde légende, crédit et droits.'] },
      { h: 'Réglages', l: ['Profil, balance des blancs (pipette sur une zone neutre), exposition, contraste, hautes lumières, ombres, blancs, noirs.', 'Texture, clarté, correction du voile, vibrance, saturation ; courbes RVB et par couche ; TSL sur huit teintes ; étalonnage des ombres, tons moyens et hautes lumières.', 'Netteté, réduction du bruit, corrections d’objectif (distorsion, vignetage, aberrations), vignetage créatif et grain.', 'Recadrer et redresser (R), perspective, masques linéaires et radiaux pour des réglages locaux, correcteur de taches (Q), LUT .cube.'] },
      { h: 'Gagner du temps', l: ['Préréglages prêts à l’emploi, et les vôtres ; instantanés pour comparer deux versions ; historique pas à pas.', 'Export JPEG, PNG, WebP, TIFF 8 bits ou TIFF 16 bits (impression, étalonnage), à la taille voulue, avec les métadonnées de la photo.'] }
    ] },
  { id: 'atelier-effets', titre: 'Effets spéciaux de cinéma', espaces: ['atelier'], ecrans: ['atelier', 'atelier-effets', 'atelier-video'], motscles: 'effets cinéma look particules brume reflet objectif projecteur halo lumière fumigènes confettis neige pluie éclair vhs pellicule bandes cinéma grain',
    resume: 'Un look de film en un clic, puis chaque effet réglé à la main, sur un visuel comme sur une vidéo.',
    sections: [
      { h: 'Looks', p: ['Le volet « ✦ Effets spéciaux de cinéma » propose une trentaine d’ambiances (épopée, héroïque, nuit de stade, tribune en feu, victoire, saga nordique, polar, noir et blanc dramatique, archive 16 mm, Super 8, VHS, néon, désert, brume du matin, tempête…), chacune montrée sur votre photo.'] },
      { h: 'Réglages', l: ['Couleur : exposition, contraste, température, virage ombres et lumières, sans blanchiment, couleur sélective, bichromie.', 'Lumière : halo (bloom), halation, traînées anamorphiques, rayons, brume, reflets d’objectif (anamorphique, projecteur, soleil), fuites de lumière.', 'Matière : grain, vignetage, aberration chromatique, pellicule abîmée, brûlure, VHS, éclairs ; flou de mouvement, effet maquette et zone nette.', 'Particules animées (fumigènes, confettis, feu d’artifice, paillettes, bokeh, braises, étincelles, poussière dorée, neige, pluie, cendres, lueurs, lucioles) : elles bougent dans les vidéos et les visuels animés.', '« Protéger les textes » garde titres et logo nets par-dessus les effets.'] }
    ] },
  { id: 'atelier-affiches', titre: 'Affiches de film', espaces: ['atelier'], ecrans: ['atelier', 'atelier-affiches'], motscles: 'affiche film cinéma poster titre générique lauriers étoiles blockbuster épique polar western horreur',
    resume: 'Des affiches de cinéma originales pour annoncer un match ou raconter une saison.',
    sections: [
      { h: 'Choisir', p: ['« Parcourir les gabarits » › Affiches de film : 57 affiches, dix-neuf genres en trois variantes (épopée, super-héros, saga nordique, fantasy, bande-annonce, archives du club, double exposition, action, thriller, science-fiction, rétro 80, western, film noir, comédie, drame, documentaire, face-à-face, teaser, guerre), aux formats 4:5, 9:16 et 1:1.'] },
      { h: 'Personnaliser', l: ['Titres en matière : or massif, acier brossé, chrome, feu, néon, glace, coucher de soleil rétro, relief 3D, double contour, gravé dans la pierre, ombre longue, impression décalée, pochoir, lumière. Bloc de générique, étoiles et lauriers modifiables.', 'Les citations et les lauriers sont des emplacements à remplir par la rédaction de Casa Besports : n’y mettez jamais un avis inventé ni un nom de festival réel.', 'Les affiches sont des créations originales : ni titre de film, ni logo de studio, ni personnage existant.'] }
    ] },
  { id: 'atelier-casa', titre: 'Gabarits et bandeaux Casa', espaces: ['atelier'], ecrans: ['atelier', 'atelier-casa', 'atelier-charte'], motscles: 'gabarit casa bandeau match club réseaux charte direction artistique league spartan noir blanc rouge',
    resume: 'Les visuels à l’identité Casa Besports : bandeaux, matchs, clubs, réseaux sociaux.',
    sections: [
      { h: 'Les catégories', l: ['Bandeau Casa : le titre posé sur des bandes noires, comme le logo ; « Le symbole BE+ » met en avant la variante courte du logo.', 'Casa · Match, Casa · Club, Casa · Réseaux : 84 gabarits (jour de match, score en direct, mi-temps, composition, homme du match, classement, podium, duel, nouvelle recrue, compte à rebours, hommage, bénévoles, inscriptions, coulisses, grosse stat, flash info, sondage, carrousel, avant / après, mosaïque, live, le saviez-vous, récap en chiffres…), chacun en trois variantes.', 'Quatorze styles de bandeau : plein, pleine largeur, bloc, contour, décalé, en escalier, incliné, souligné, surligné, étiquette, numéroté, ruban défilant, tampon et direct (rouge). Le style se change dans le panneau du texte.'] },
      { h: 'La charte', l: ['Titres en capitales League Spartan, en noir et blanc ; le rouge est réservé au direct et à l’urgence ; coins droits.', 'Le bouton « Charte DA » montre la galerie des bandeaux et les règles à respecter.'] }
    ] },
  { id: 'atelier-motivation', titre: 'Motivation : photo en fond et texte proposé par l’IA', espaces: ['atelier'], ecrans: ['atelier', 'atelier-motivation'], motscles: 'motivation citation inspiration texte ia claude photo instagram phrase placer',
    resume: 'Des publications Instagram à texte de motivation, avec des phrases proposées d’après la photo.',
    sections: [
      { h: 'Les gabarits', p: ['« Parcourir les gabarits » › Motivation : douze mises en page (bandeau Casa, citation centrée, titre bas, un mot géant, cadre blanc, trois règles, titre vertical, minimal, affiche typographique…), chacune en couleur, en noir et blanc et en version cinéma.'] },
      { h: 'Texte de motivation', l: ['L’encart « ✦ Texte de motivation » s’ouvre avec ces gabarits (et sur tout visuel avec une photo). Choisissez le ton, la longueur et le thème, puis « Proposer des textes ».', 'Claude regarde la photo (geste, lumière, lieu, météo) et propose six phrases originales en français, avec le mot à mettre en valeur. Aucune citation n’est attribuée à une personne réelle ; aucun nom, score ni date n’est inventé.', 'Sans IA, une bibliothèque maison d’environ 150 phrases est choisie d’après l’ambiance mesurée de la photo.', 'Un clic applique la phrase au texte sélectionné. « Placer le texte » le pose dans la zone la plus calme de l’image, en blanc ou en noir selon la luminosité, avec un voile si besoin.'] }
    ] },
  { id: 'atelier-archives', titre: 'Archiver les créations', espaces: ['atelier'], ecrans: ['atelier', 'atelier-archives', 'atelier-versions'], motscles: 'archive archiver désarchiver ranger anciennes zip exporter importer sauvegarde',
    resume: 'Ranger les créations terminées sans rien perdre, et les sauvegarder dans un fichier .zip.',
    sections: [
      { h: 'Archiver', l: ['« Mes créations » › bouton « Archiver » sur une création : elle quitte la liste courante et rejoint l’onglet « Archives », avec ses versions et ses photos.', '« Ranger les créations non modifiées depuis… » (3, 6, 12 ou 24 mois) archive d’un coup les créations anciennes.', 'Sur le serveur, son auteur, les chefs d’édition et l’administrateur peuvent archiver une création.'] },
      { h: 'Consulter et reprendre', l: ['Une création archivée s’ouvre en lecture seule : « Désarchiver » la rend de nouveau modifiable, « Enregistrer une copie » en fait une nouvelle création.', 'La recherche des archives porte aussi sur le motif d’archivage ; un filtre par année est proposé.'] },
      { h: 'Fichier .zip', l: ['« Exporter (.zip) » sur une archive, ou « Exporter toutes les archives » : les créations (visuels, textes, réglages, versions), leurs photos avec légende, crédit et droits, et un aperçu JPEG de chaque visuel.', 'Les photos d’agence ne sont pas copiées (droits de l’agence) : seule leur référence est gardée.', '« Importer une archive (.zip) » restaure les créations sur un autre appareil ou un autre compte ; une création déjà présente à l’identique n’est pas dupliquée.'] }
    ] },
  { id: 'atelier-montage-video', titre: 'Studio Vidéo : montage auto et séries', espaces: ['atelier'], ecrans: ['atelier', 'atelier-video'], motscles: 'montage auto automatique vidéo série épisodes reels tiktok youtube court long résumé temps forts ralenti replay cinéma cinématique 24 images bandes cinémascope vertical carré cadre suit action exporter série 4k demande ia',
    resume: 'Écrivez ce que vous voulez : le Studio analyse vos rushes, repère les temps forts et monte la vidéo, la série d’épisodes courts ou la version longue demandée, en mode cinéma avec ralentis et replays.',
    sections: [
      { h: 'Demander', l: ['« ✦ Montage auto » en haut du Studio Vidéo : déposez vos rushes (vidéos, photos, musique) puis écrivez votre demande, par exemple « 3 épisodes de 20 s pour Reels, ralentis sur les temps forts, mode cinéma, et une version de 1 minute pour YouTube ».', 'Les réglages se remplissent d’après la demande (style, ralentis, replays, ordre, look, formats, durées, titre) et restent modifiables avant « Analyser et monter ». Seul ce qui est demandé est monté : « une vidéo de 45 s » donne une vidéo, « 3 épisodes et une version longue » donne les deux.'] },
      { h: 'L’analyse', p: ['Chaque rush est lu sur votre appareil : le mouvement, le son (clameur, coup de sifflet), la netteté et la lumière donnent les temps forts. L’analyse est gardée : relancer un montage avec les mêmes rushes est immédiat.'] },
      { h: 'Le montage', l: ['Mode cinéma : 24 images/s, look de cinéma, bandes 2,39:1 en 16:9, carton titre, rampes de ralenti sur les temps forts et replays courts avec le volet Casa. Les styles dynamique et émotion ont leurs transitions et leurs looks.', 'Série : chaque épisode prend ses propres temps forts sans répéter ceux des autres ; « Épisode 1 / 3 » s’affiche au début. La version longue reprend le meilleur, dans l’ordre du match ou en montée en tension.', 'En vertical, en carré ou en 4:5, le cadre suit l’action : il se place là où ça bouge le plus et se déplace en douceur.', 'Si les rushes sont trop courts pour la durée demandée, la version reste plus courte et le Studio le signale.'] },
      { h: 'Corriger avant d’exporter', l: ['Barre de la série : chaque version s’ouvre dans le Studio, où tout se règle (entrée, sortie, vitesse, cadrage, transitions, titres, musique).', '« Adapter en » ajoute une copie dans un autre format, cadre recalculé ; « Refaire » propose une autre construction ; « Retirer » supprime la version ; « Enregistrer la série » la garde dans Créations.'] },
      { h: 'Exporter', l: ['« Exporter la série » exporte toutes les versions à la suite en qualité maximale : définition des rushes jusqu’en 4K, MP4 H.264 (VP9 ou AV1 si le navigateur n’a pas H.264), son AAC 320 kbit/s normalisé à −14 LUFS.', 'L’export se fait sur votre appareil, image par image : gardez l’onglet ouvert jusqu’à la fin.'] },
      { h: 'L’IA', p: ['Sur claude.ai, ou sur casabesports.fr quand la clé IA est configurée, l’IA lit votre demande (formats, durées, style, titres d’épisodes). Elle ne reçoit que votre texte et des chiffres (nom, durée et définition des rushes, instants des temps forts), jamais les images ni le son. Sans IA, la demande est lue par les règles intégrées.'] }
    ] },
  { id: 'atelier-video-pro', titre: 'Studio Vidéo : export de qualité pro', espaces: ['atelier'], ecrans: ['atelier', 'atelier-video', 'atelier-video-export'], motscles: 'vidéo export mp4 webm mkv h264 h265 hevc av1 vp9 4k dci 23,976 25 30 60 débit images clés gif png séquence wav lufs sonie sous-titres',
    resume: 'Exporter une vidéo image par image, jusqu’en 4K, sans perte d’image ni dépendance à la puissance de l’appareil.',
    sections: [
      { h: 'Préréglages', l: ['Réseaux sociaux (1080 × 1920, −14 LUFS), YouTube 4K, Télévision HD (25 i/s, −23 LUFS), Cinéma 4K DCI (4096 × 2160, 24 i/s), Master de montage (chaque image est une image clé), Web léger, GIF, séquence PNG, son seul.'] },
      { h: 'Réglages', l: ['Fichier : MP4, WebM ou MKV ; codec H.264, H.265, AV1, VP9 ou VP8 selon ce que sait encoder le navigateur (Chrome, Edge et Safari récents).', 'Formats 16:9, 9:16, 1:1, 4:5, DCI 1,9:1 et cinémascope 2,39:1 ; de 720p à 2160p ; 23,976, 24, 25, 29,97, 30, 48, 50, 59,94 et 60 images par seconde.', 'Qualité maître, haute, standard ou légère, ou débit imposé ; débit constant pour la diffusion ; images clés toutes les 1, 2 ou 5 s, ou à chaque image.', 'Son AAC ou Opus jusqu’à 320 kb/s, mixé hors ligne (plans, musique, effets sonores) et normalisé en LUFS, crête plafonnée à −1 dB ; WAV 24 bits séparé.', 'Sous-titres incrustés ou en fichier .srt ; « Enregistrer directement sur le disque » pour les très gros fichiers (sur la plateforme).'] },
      { h: 'Bon à savoir', l: ['Le rendu ne dépend plus de la lecture en direct : l’onglet peut passer en arrière-plan, rien n’est sauté.', 'Les MP4, MOV, WebM et MKV sont décodés image par image, rotation des téléphones comprise ; les autres formats lisibles passent par le lecteur du navigateur, plus lentement.', 'L’ancien export en temps réel reste disponible en bas de la fenêtre.'] }
    ] },
  { id: 'atelier-video-outils', titre: 'Studio Vidéo : étalonnage, oscilloscopes, sous-titres', espaces: ['atelier'], ecrans: ['atelier', 'atelier-video'], motscles: 'étalonnage plan studio photo lut forme d onde parade vecteurscope histogramme zébras sous-titres srt vtt inversée fondu ducking musique vitesse',
    resume: 'Les outils de finition d’un logiciel de montage, plan par plan.',
    sections: [
      { h: 'Par plan', l: ['« Étalonnage pro (Studio Photo) » : courbes, roues, TSL, LUT et masques sur l’image du plan, appliqués à chaque image en aperçu comme à l’export.', 'Lecture inversée, fondus sonores d’entrée et de sortie (calculés à l’export) ; vitesses de ×0,1 (sources à 240 images/s) à ×8.'] },
      { h: 'Contrôle de l’image', l: ['Oscilloscopes sous l’aperçu : forme d’onde, parade RVB, vecteurscope avec la ligne des carnations, histogramme.', 'Zébras : les zones brûlées (au-delà de 95 %) sont rayées dans l’aperçu, jamais dans la vidéo.'] },
      { h: 'Son et sous-titres', l: ['« Baisser la musique quand les plans ont du son » atténue automatiquement la musique sous les commentaires ou l’ambiance du stade ; musique en boucle si besoin.', 'Sous-titres : import .srt ou .vtt, saisie dans le panneau, export .srt ou .vtt ; bandeau noir et texte blanc, en bas ou en haut, taille réglable.'] }
    ] },
  { id: 'atelier-visuel-anime', titre: 'Visuel animé : une vidéo en fond d’un gabarit', espaces: ['atelier'], ecrans: ['atelier', 'atelier-visuel-anime'], motscles: 'visuel animé vidéo fond reel story mp4 gabarit motivation casa',
    resume: 'Transformer n’importe quel visuel en Reel : la vidéo en fond, les textes et effets par-dessus.',
    sections: [
      { h: 'Utiliser', l: ['« ▶ Vidéo en fond (visuel animé) » sous « Ajouter des photos » : la vidéo remplace la photo du visuel affiché.', 'Dans le panneau « Visuel animé » : début et fin, son ou non, volume, « ▶ Aperçu animé ».', 'Exporter la vidéo : MP4 ou WebM, codec, images par seconde, qualité et sonie ; le format est celui du visuel (4:5, 9:16…).'] },
      { h: 'Bon à savoir', l: ['La vidéo reste sur cet appareil : elle n’est pas envoyée avec les créations partagées.', '« Retirer la vidéo » rend sa photo au visuel.'] }
    ] },
  { id: 'atelier-conversions', titre: 'Formats de studio : conversions par le serveur', espaces: ['atelier', 'admin'], ecrans: ['atelier-video', 'atelier-video-export'], motscles: 'prores dnxhr mxf mov broadcast hevc 10 bits ffv1 flac mp3 conversion ffmpeg mts avi',
    resume: 'Sur la plateforme, ffmpeg produit les formats que les navigateurs ne savent pas écrire.',
    sections: [
      { h: 'À l’export', p: ['« Après l’export, convertir aussi en » : Apple ProRes 422 HQ, 4444, LT ou Proxy (.mov), Avid DNxHR HQX (.mov) ou HQ (.mxf), H.264 broadcast 50 Mb/s, H.264 haute qualité, MOV pour QuickTime et Final Cut, H.265 10 bits, AV1 10 bits, VP9, FFV1 sans perte, GIF à palette optimisée, WAV, FLAC, MP3.'] },
      { h: 'À l’import', p: ['Un fichier que le navigateur ne lit pas (MTS, AVI, MXF, WMV, ProRes…) affiche « Convertir (serveur) » : une version de montage H.264 est créée et ajoutée au Studio Vidéo.'] },
      { h: 'Réglages du serveur', p: ['ffmpeg est inclus dans l’image Docker. Variables facultatives : MEDIA_MAX_MB (taille maximale envoyée, 8 192 Mo par défaut), MEDIA_JOBS (conversions simultanées), MEDIA_TIMEOUT_S, MEDIA_TMP. Les fichiers sont effacés après 24 h et ne sont jamais publics.'] }
    ] },
  { id: 'atelier-boutique', titre: 'Studio Boutique : créer un article', espaces: ['atelier'], ecrans: ['atelier', 'atelier-boutique'], motscles: 'boutique merch textile t-shirt sweat hoodie jogging short maillot casquette bob bonnet écharpe tote sac mug verre gobelet gourde stylo maquette marquage zone',
    resume: 'Concevoir un article de la boutique sur une maquette réaliste : support, coloris, zones d’impression, marquage.',
    sections: [
      { h: 'Les étapes', l: ['« Studio Boutique » dans la barre du haut de l’Atelier.', 'À gauche : le support (textile, maillots, accessoires, sacs, objets), les coloris proposés, la technique de marquage, les tailles et la description du support de base.', 'Au centre : la maquette, de face, de dos ou de profil, avec les zones d’impression en pointillés et leurs dimensions réelles ; en bas, l’article dans chaque coloris.', 'À droite, « Création » : choisissez une zone, ajoutez un logo (dont le symbole BE+), un texte, le visuel en cours de l’Atelier, une photo ou une image importée, puis réglez taille, position, rotation, encre et contours.', 'Glissez un élément sur la maquette pour le déplacer ; Ctrl + molette change sa taille, les flèches l’ajustent, Suppr l’efface, Ctrl + Z annule.'] },
      { h: 'Coloris et encre', l: ['Un clic sur une pastille affiche le coloris ; un second clic l’ajoute aux coloris proposés ou l’en retire.', 'Les logos de la charte sont utilisés tels quels ; le logotype, les lettres du symbole BE+ et les textes en « contraste auto » prennent l’encre la plus lisible sur chaque coloris.', '« Fond de l’image » retire un fond blanc ou noir ; « Encre » passe une image en une seule couleur (sérigraphie, gravure, tampographie).', 'Une zone peut avoir sa propre technique : par exemple la broderie au cœur et le transfert au dos.'] },
      { h: 'Bon à savoir', l: ['Ce qui dépasse une zone n’est pas imprimé : un avertissement le signale.', 'Changer de support garde le dessin : chaque élément rejoint la zone équivalente (cœur, poitrine, dos…).', 'Les articles s’enregistrent automatiquement dans « Mes articles », sur cet appareil.', 'Les maquettes sont calculées par l’Atelier (relief du tissu, objets en 3D) : ce sont des visuels numériques, pas des photos.', '« 5D », « Promo » et « Commande perso », en haut du studio : la vue en volume et ses exports, les formats de lancement et le dossier export, les commandes nominatives (voir leurs fiches).'] }
    ] },
  { id: 'atelier-boutique-maillots', titre: 'Maillots de football, de basket et de rugby', espaces: ['atelier'], ecrans: ['atelier-boutique'], motscles: 'maillot sublimation motif rayures cerceaux damier col nom numéro flocage personnalisation',
    resume: 'Motif sublimé, couleurs du club, col, manches, nom et numéro.',
    sections: [
      { h: 'Onglet Maillot', l: ['Douze motifs : uni, rayures, fines rayures, cerceaux, deux moitiés, écharpe diagonale, chevrons, dégradé, damier, bandes poitrine, côtés, empiècement.', 'Couleur principale, secondaire (le motif) et finitions (col, poignets) ; col rond ou en V pour le football ; manches avec le motif ou unies.', 'Nom et numéro au dos, numéro devant en option : police, couleur, contour, arrondi du nom.', '« L’acheteur choisit son nom et son numéro » : la fiche du maillot propose alors la personnalisation dans la boutique.'] },
      { h: 'Technique et prix', p: ['Par défaut tout est sublimé (motif, couleurs et marquages) : le prix compte une sublimation intégrale. En flocage, le nom et chaque numéro sont comptés à l’unité.'] }
    ] },
  { id: 'atelier-boutique-prix', titre: 'Prix conseillé et barème', espaces: ['atelier'], ecrans: ['atelier-boutique'], motscles: 'prix coût revient marge coefficient tva barème quantité seuil rentabilité abonnés positionnement',
    resume: 'Comment le Studio Boutique calcule un prix de vente, et comment ajuster son barème.',
    sections: [
      { h: 'Le calcul', l: ['Coût de revient par pièce : support + marquage de chaque zone (selon la technique, la taille réelle du dessin et, en sérigraphie ou tampographie, le nombre de couleurs) + emballage + frais de mise en route répartis sur la quantité produite.', 'Prix conseillé : coût × coefficient de positionnement (accessible 2,0 ; standard 2,4 ; premium 2,8 ; collector 3,2), TVA comprise, arrondi à un prix rond.', 'Repères affichés : marge brute, taux de marque, coefficient réel, prix et marge avec la remise abonnés (−10 %), pièces à vendre pour couvrir la production, prix des pièces comparables de la boutique, prix selon la quantité.'] },
      { h: 'Le barème', l: ['Tous les montants sont indicatifs et modifiables (onglet Prix › Modifier le barème) : remplacez-les par les devis de vos fournisseurs.', 'Sur la plateforme, l’administrateur et les chefs d’édition enregistrent le barème pour toute l’équipe.', '« Votre prix » remplace le prix conseillé : marges et repères se recalculent. Les frais de livraison ne sont pas compris.'] }
    ] },
  { id: 'atelier-boutique-exports', titre: 'Studio Boutique : visuels, fichiers d’impression, fiche technique', espaces: ['atelier'], ecrans: ['atelier-boutique'], motscles: 'export jpeg png 300 dpi fichier impression planche fiche technique pdf pack instagram détouré',
    resume: 'Ce que le Studio Boutique fournit pour vendre et faire fabriquer un article.',
    sections: [
      { h: 'Exporter…', l: ['Visuels boutique : JPEG 1 200 × 1 200 sur fond studio, pour chaque coloris et chaque vue ; visuels détourés en PNG transparents.', 'Planche de présentation 1 920 × 1 080 : vues, coloris, technique, tailles, prix.', 'Fichiers d’impression : un PNG transparent par zone, aux dimensions réelles, à 300 dpi (la résolution est inscrite dans le fichier) ; pour un maillot sublimé, panneaux avant et dos à 100 dpi avec un contour indicatif.', 'Fiche technique PDF : support, coloris, tailles, techniques, cotes et position de chaque dessin, couleurs, polices, coût et prix.', 'Pack boutique (.json) : l’article prêt à importer sur le site ou dans l’application.'] },
      { h: 'Instagram', p: ['« Créer un visuel Instagram » ajoute la maquette à Mes photos et la pose sur le visuel en cours : il ne reste qu’à choisir un gabarit.'] }
    ] },
  { id: 'boutique-creations', titre: 'Ajouter un article créé à la boutique', espaces: ['atelier', 'redaction', 'admin'], ecrans: ['atelier-boutique', 'boutique'], motscles: 'ajouter boutique publier brouillon retirer pack importer créations casa site application',
    resume: 'De l’Atelier à la collection « Créations Casa » du site et de l’application.',
    sections: [
      { h: 'Sur la plateforme', l: ['Studio Boutique › « Ajouter à la boutique » : l’article part sur le serveur avec un visuel par coloris et par vue, sa fiche et sa création modifiable.', 'Brouillon : visible par l’équipe seulement. Publié : visible par tous dans la collection « Créations Casa » du site et de l’application.', 'Les rédacteurs envoient en brouillon ; l’administrateur et les chefs d’édition publient, retirent ou suppriment, depuis l’Atelier (Mes articles) ou depuis la boutique du site (« Articles de l’Atelier »).', 'Le coût de revient et la création restent internes : le public ne voit que la fiche, le prix et les visuels.'] },
      { h: 'Sans serveur (aperçu, application seule)', l: ['« Ajouter à la boutique » enregistre l’article et télécharge un pack .casa-boutique.json.', 'Sur le site ou dans l’application : Boutique › Articles de l’Atelier › Importer un pack. Les articles importés restent sur cet appareil ; « Retirer », « Remettre en boutique » et « Supprimer » les gèrent.'] },
      { h: 'Avant de publier', l: ['Confirmez la matière et la fabrication avec votre fournisseur : le texte proposé n’invente rien, mais la description du support de base reste à vérifier.', 'Vérifiez les droits des images importées et des photos utilisées.'] }
    ] }
];
if (typeof window !== 'undefined') window.CASA_AIDE = CASA_AIDE;

